:root {
  --primary: #122A52;
  --accent: #3B6FE0;
  --bg: #F3F5FA;
  --surface: #FFFFFF;
  --text: #1B2333;
  --muted: #6B7280;
  --border: #D6DCE8;
  --soft: #DCE4F3;
  --radius: 8px;
  --font: "Segoe UI", -apple-system, BlinkMacSystemFont, Roboto, Helvetica, Arial, sans-serif;
}

* { box-sizing: border-box; }
html, body { margin: 0; }
body { font-family: var(--font); font-size: 14px; color: var(--text); background: var(--bg); }
[hidden] { display: none !important; }

.wrap { padding: 20px 24px 8px; }
.head { margin-bottom: 14px; }
.head h2 { font-size: 17px; margin: 0; }
.head p { margin: 4px 0 0; color: var(--muted); font-size: 13px; }

.grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
  gap: 16px;
}

.card {
  position: relative;
  display: flex;
  flex-direction: column;
  gap: 10px;
  min-height: 150px;
  padding: 18px;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: calc(var(--radius) * 1.25);
  box-shadow: 0 1px 2px rgba(16, 24, 40, .05);
  cursor: pointer;
  text-align: left;
  font: inherit;
  color: inherit;
  transition: border-color .15s ease, box-shadow .15s ease, transform .15s ease;
}
.card:hover, .card:focus-visible {
  border-color: var(--accent);
  box-shadow: 0 8px 20px rgba(18, 42, 82, .12);
  transform: translateY(-2px);
  outline: none;
}

.icon {
  width: 42px; height: 42px;
  border-radius: var(--radius);
  background: var(--soft);
  color: var(--primary);
  display: flex; align-items: center; justify-content: center;
}
.icon svg { width: 22px; height: 22px; }

.card h3 { margin: 0; font-size: 15px; color: var(--primary); }
.card .desc { margin: 0; color: var(--muted); font-size: 13px; line-height: 1.45; flex: 1; }

.open {
  align-self: flex-end;
  display: inline-flex; align-items: center; gap: 6px;
  height: 32px; padding: 0 14px;
  border-radius: var(--radius);
  background: var(--primary); color: #fff;
  font-weight: 600; font-size: 13px;
}
.card:hover .open { filter: brightness(1.2); }

.badge {
  position: absolute; top: 14px; right: 14px;
  padding: 2px 8px; border-radius: 999px;
  background: #FFF3D6; color: #93650B;
  font-size: 11.5px; font-weight: 700;
}

.skeleton {
  cursor: default;
  background: linear-gradient(90deg, #eef1f7 25%, #f7f9fc 50%, #eef1f7 75%);
  background-size: 200% 100%;
  animation: shimmer 1.2s infinite;
  border-color: transparent;
}
.skeleton:hover { transform: none; box-shadow: none; }
@keyframes shimmer { from { background-position: 200% 0; } to { background-position: -200% 0; } }

.empty {
  padding: 24px; text-align: center; color: var(--muted);
  background: var(--surface); border: 1px dashed var(--border); border-radius: var(--radius);
}

