.flag.tone-warn {
  background: var(--warn-bg);
  color: var(--warn);
}

.flag.tone-danger {
  background: var(--danger-bg);
  color: var(--danger);
}

.flag.tone-ok {
  background: var(--ok-bg);
  color: var(--ok);
}

.chev {
  flex: none;
  color: var(--muted);
}

button.task:hover .chev {
  color: var(--accent);
}

.more {
  align-self: flex-start;
  margin-top: 6px;
  padding: 4px 6px;
  border: 0;
  background: transparent;
  color: var(--accent);
  font: inherit;
  font-size: 13px;
  font-weight: 600;
  cursor: pointer;
}

.none {
  margin: 10px 0 2px;
  color: var(--muted);
  font-size: 13px;
}

.empty {
  padding: 24px;
  text-align: center;
  color: var(--muted);
  background: var(--surface);
  border: 1px dashed var(--border);
  border-radius: var(--radius);
}

.skeleton {
  cursor: default;
  border-color: transparent;
  background: linear-gradient(90deg, #eef1f7 25%, #f7f9fc 50%, #eef1f7 75%);
  background-size: 200% 100%;
  animation: shimmer 1.2s infinite;
}

@keyframes shimmer {
  from {
    background-position: 200% 0;
  }
  to {
    background-position: -200% 0;
  }
}

@media (max-width: 760px) {
  .sections.cols-2 {
    grid-template-columns: 1fr;
  }

  .task-flags {
    max-width: 38%;
  }
}

