:root {
  --primary: #122A52;
  --accent: #3B6FE0;
  --surface: #FFFFFF;
  --surface-alt: #EEF1F7;
  --text: #1B2333;
  --muted: #6B7280;
  --border: #D6DCE8;
  --danger: #C0392B;
  --danger-bg: #FDEDEB;
  --info-bg: #DCE4F3;
  --radius: 8px;
  --font: "Segoe UI", -apple-system, BlinkMacSystemFont, Roboto, Helvetica, Arial, sans-serif;
}

* {
  box-sizing: border-box;
}

html, body {
  margin: 0;
  height: 100%;
  background: var(--surface);
}

body {
  color: var(--text);
  font-family: var(--font);
  font-size: 14px;
}

[hidden] {
  display: none !important;
}

.wrap {
  padding: 20px 24px;
}

.head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 12px;
}

h2 {
  margin: 0;
  font-size: 18px;
}

.x {
  border: none;
  background: none;
  font-size: 16px;
  color: var(--muted);
  cursor: pointer;
  padding: 4px 8px;
  border-radius: var(--radius);
}

.x:hover {
  background: var(--surface-alt);
}

label {
  display: block;
  font-weight: 600;
  font-size: 12.5px;
  margin: 14px 0 6px;
}

.req {
  color: var(--danger);
}

input[type=text], input[type=email], input[type=number], select {
  width: 100%;
  height: 38px;
  padding: 0 12px;
  border: 1px solid var(--border);
  border-radius: var(--radius);
  font: inherit;
  color: inherit;
  background: #fff;
}

input:focus, select:focus {
  outline: none;
  border-color: var(--accent);
  box-shadow: 0 0 0 3px rgba(59, 111, 224, 0.18);
}

input:disabled, select:disabled {
  background: var(--surface-alt);
  color: var(--muted);
  cursor: not-allowed;
}

input.invalid, select.invalid {
  border-color: var(--danger);
}

.switch-row {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-top: 16px;
  cursor: pointer;
  font-weight: 600;
}

.switch-row input {
  position: absolute;
  opacity: 0;
  pointer-events: none;
}

.switch {
  width: 38px;
  height: 22px;
  border-radius: 999px;
  background: var(--border);
  position: relative;
  transition: background 0.15s;
  flex: none;
}

.switch::after {
  content: "";
  position: absolute;
  top: 3px;
  left: 3px;
  width: 16px;
  height: 16px;
  border-radius: 50%;
  background: #fff;
  transition: left 0.15s;
  box-shadow: 0 1px 2px rgba(0, 0, 0, 0.2);
}

.switch-row input:checked + .switch {
  background: var(--primary);
}

.switch-row input:checked + .switch::after {
  left: 19px;
}

.switch-row input:disabled + .switch {
  opacity: 0.5;
}

.switch-row input:focus-visible + .switch {
  box-shadow: 0 0 0 3px rgba(59, 111, 224, 0.25);
}

.field-note {
  color: var(--muted);
  font-size: 12px;
  margin-top: 6px;
}

.info {
  background: var(--info-bg);
  color: var(--primary);
  border-radius: var(--radius);
  padding: 10px 12px;
  font-size: 12.5px;
  margin-top: 16px;
}

.msg {
  border-radius: var(--radius);
  padding: 10px 12px;
  font-size: 13px;
  margin-bottom: 4px;
}

.msg.error {
  background: var(--danger-bg);
  color: var(--danger);
}

.msg.info {
  background: var(--info-bg);
  color: var(--primary);
}

.actions {
  display: flex;
  justify-content: flex-end;
  gap: 8px;
  margin-top: 22px;
}

.btn-primary, .btn-secondary {
  height: 38px;
  padding: 0 18px;
  border-radius: var(--radius);
  border: 1px solid transparent;
  font: inherit;
  font-weight: 600;
  cursor: pointer;
}

.btn-primary {
  background: var(--primary);
  color: #fff;
}

.btn-primary:hover:not(:disabled) {
  filter: brightness(1.2);
}

.btn-secondary {
  background: #fff;
  color: var(--text);
  border-color: var(--border);
}

.btn-secondary:hover:not(:disabled) {
  background: var(--surface-alt);
}

button:disabled {
  opacity: 0.6;
  cursor: default;
}

.row {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 12px;
}

.row > div > label {
  margin-top: 14px;
}

input[type=number]::-webkit-inner-spin-button {
  opacity: 0.5;
}

.hint {
  color: var(--muted);
  font-size: 12px;
  margin-top: 6px;
}

.hint.warn {
  color: var(--danger);
}

.link {
  border: none;
  background: none;
  color: var(--accent);
  font: inherit;
  font-size: 12px;
  font-weight: 600;
  padding: 0;
  cursor: pointer;
}

.link:hover {
  text-decoration: underline;
}

/* R2: "cari dulu, baru buat" - daftar nama mirip */
.similar {
  margin-top: 8px;
  border: 1px solid #F1D9A6;
  background: #FFF8E6;
  border-radius: var(--radius);
  padding: 8px 12px;
  font-size: 12.5px;
}

.similar-title {
  font-weight: 600;
  color: #8A5A00;
  margin-bottom: 4px;
}

.similar ul {
  margin: 0;
  padding-left: 18px;
}

.similar li {
  margin: 2px 0;
}

.similar .meta {
  color: var(--muted);
}

srcDoc.js:
// cwKomponenForm - form Tambah/Ubah Komponen di mdlKomponen. Hanya tampilan; simpan lewat
// KomponenCtrl.save(). Aturan nomor dicek ringan di sini untuk umpan balik cepat; aturan final di DB
// (trg_component_check).
const $ = id => document.getElementById(id);
let lastKey = null;
let busy = false;
let groups = [];
let isEdit = false;
let lastSuggest = null;   // saran nomor untuk kelompok yang sedang dipilih

function applyTheme(t) {
  t = t || {};
  const r = document.documentElement.style;
  if (t.primaryColor) r.setProperty('--primary', t.primaryColor);
  if (t.borderRadius) r.setProperty('--radius', t.borderRadius);
  if (t.fontFamily && t.fontFamily !== 'System Default') r.setProperty('--font', `${t.fontFamily}, "Segoe UI", Arial, sans-serif`);
}

function showMessage(m) {
  const box = $('msg');
  if (!m || !m.text) {
    box.hidden = true;
    box.textContent = '';
    return;
  }
  box.className = `msg ${m.type || 'info'}`;
  box.textContent = m.text;
  box.hidden = false;
}

function fillSelect(sel, options, selected, placeholder) {
  sel.innerHTML = '';
  if (placeholder) {
    const ph = document.createElement('option');
    ph.value = '';
    ph.textContent = placeholder;
    sel.appendChild(ph);
  }
  (options || []).forEach(o => {
    const opt = document.createElement('option');
    opt.value = o.value;
    opt.textContent = o.label;
    sel.appendChild(opt);
  });
  sel.value = selected || '';
}

function currentGroup() {
  return groups.find(g => g.code === $('group').value) || null;
}

function suggestionOf(g) {
  return g && g.next_no !== null && g.next_no !== undefined ? Number(g.next_no) : null;
}

function updateHint() {
  const g = currentGroup();
  const hint = $('numberHint');
  const btn = $('btnSuggest');
  hint.classList.remove('warn');
  btn.hidden = true;
  if (!g) {
    hint.textContent = 'Select a group first.';
    return;
  }
  // R19: nomor = posisi. Tambah: nomor terpakai -> komponen itu dan yang menempel di bawahnya +10 (fn_component_make_room).
  // Edit (kelompok sama): pindah posisi seperti Master Options, yang di antaranya bergeser 10 (fn_component_move).
  const base = `Range ${g.range_start}–${g.range_end}, multiples of 10.`;
  const range = `${base} A number already in use moves that component (and the ones right after it) down by 10.`;
  if (isEdit) {
    hint.textContent = `${base} Moving to a number in use shifts the components in between by 10 (like the Order in Master Options).`;
    return;
  }
  const s = suggestionOf(g);
  if (s === null) {
    hint.textContent = `${range} This group range is full.`;
    hint.classList.add('warn');
    return;
  }
  hint.textContent = `${range} Suggested next number: ${s}.`;
  btn.hidden = $('number').value === String(s);
}

// Tambah: saat kelompok diganti, nomor ikut saran baru - kecuali user sudah mengetik nomor sendiri
function onGroupChange() {
  const next = suggestionOf(currentGroup());
  if (!isEdit) {
    const typed = $('number').value;
    if (typed === '' || typed === String(lastSuggest)) {
      $('number').value = next === null ? '' : String(next);
    }
  }
  lastSuggest = next;
  $('group').classList.remove('invalid');
  updateHint();
}

// ---- nama mirip (R2: "cari dulu, baru buat") ----
let similarTimer = null;
let lastQuery = null;
const norm = s => String(s || '').trim().replace(/\s+/g, ' ').toLowerCase();

function renderSimilar(m) {
  const list = m.similar || [];
  const show = list.length > 0 && norm(m.similarFor) === norm($('name').value);
  $('similar').hidden = !show;
  const ul = $('similarList');
  ul.innerHTML = '';
  if (!show) return;
  list.forEach(x => {
    const li = document.createElement('li');
    li.textContent = x.label;
    if (x.info) {
      const meta = document.createElement('span');
      meta.className = 'meta';
      meta.textContent = ` · ${x.info}`;
      li.appendChild(meta);
    }
    ul.appendChild(li);
  });
}

function querySimilar() {
  clearTimeout(similarTimer);
  similarTimer = setTimeout(() => {
    const q = $('name').value.trim().replace(/\s+/g, ' ');
    if (q === lastQuery) return;
    lastQuery = q;
    appsmith.updateModel({ similarQuery: q });
    appsmith.triggerEvent('onSearch');
  }, 350);
}

// Isi ulang field hanya saat modal dibuka (key berubah) - busy/message tidak menghapus ketikan user
function fillForm(m) {
  const f = m.form || {};
  isEdit = m.mode === 'edit';
  groups = m.groups || [];
  $('title').textContent = isEdit ? 'Edit Component' : 'Add Component';
  fillSelect($('group'), groups.map(g => ({
    value: g.code,
    label: `${g.code} · ${g.name} (${g.range_start}–${g.range_end})`,
  })), f.group_code, 'Select group');
  lastSuggest = suggestionOf(currentGroup());
  $('number').value = f.number === null || f.number === undefined ? '' : String(f.number);
  $('name').value = f.name || '';
  fillSelect($('status'), m.statusOptions, f.status || 'ACTIVE');
  $('statusBox').hidden = !isEdit;
  $('addInfo').hidden = isEdit;
  $('editNote').hidden = !isEdit;
  $('btnSave').dataset.label = 'Save';
  lastQuery = isEdit ? $('name').value.trim() : null;
  ['group', 'number', 'name'].forEach(id => $(id).classList.remove('invalid'));
  updateHint();
  (isEdit ? $('name') : ($('group').value ? $('name') : $('group'))).focus();
}

function setBusy(v) {
  busy = v;
  $('btnSave').disabled = v;
  $('btnCancel').disabled = v;
  $('btnX').disabled = v;
  $('btnSave').textContent = v ? 'Saving…' : ($('btnSave').dataset.label || 'Save');
}

function render(model) {
  const m = model || {};
  if (m.key !== lastKey) {
    lastKey = m.key;
    fillForm(m);
  }
  showMessage(m.message);
  setBusy(!!m.busy);
  renderSimilar(m);
}

function validate(g, numText, name) {
  if (!g) return ['group', 'Group is required.'];
  if (!/^\d+$/.test(numText)) return ['number', 'Number must be a whole number.'];
  const n = Number(numText);
  if (n % 10 !== 0) return ['number', 'Component number must be a multiple of 10.'];
  if (n < g.range_start || n > g.range_end) {
    return ['number', `Number must be in the range ${g.range_start}–${g.range_end} for group ${g.name}.`];
  }
  if (!name) return ['name', 'Component name is required.'];
  return null;
}

function submit() {
  if (busy) return;
  const g = currentGroup();
  const numText = $('number').value.trim();
  const name = $('name').value.trim().replace(/\s+/g, ' ');
  ['group', 'number', 'name'].forEach(id => $(id).classList.remove('invalid'));
  const err = validate(g, numText, name);
  if (err) {
    $(err[0]).classList.add('invalid');
    $(err[0]).focus();
    showMessage({ type: 'error', text: err[1] });
    return;
  }
  appsmith.updateModel({
    group_code: g.code,
    number: Number(numText),
    name,
    status: $('status').value,
