async function () {
  const hadToken = !!appsmith.store.token;
  try {
    await Auth.load();
  } catch (e) {
    showAlert('Could not load profile: ' + Util.cleanError(e && e.message), 'error');
    return false;
  }
  if (!Auth.me) {
    await removeValue('token');
    if (hadToken) showAlert('Session expired. Please log in again.', 'warning');
    navigateTo('Login');
    return false;
  }
  if (Auth.me.must_change_password) {
    navigateTo('Login', {
      mode: 'ganti'
    });
    return false;
  }
  if (Auth.requiredPerm && !Auth.can(Auth.requiredPerm)) {
    showAlert(`Role ${Auth.me.role_label} has no access to this page.`, 'warning');
    navigateTo('Home');
    return false;
  }
  for (const q of Auth.pageQueries()) {
    try {
      await q.run();
    } catch (e) {
      const msg = e && e.message;
      if (Util.isSessionError(msg)) {
        await removeValue('token');
        showAlert('Session expired. Please log in again.', 'warning');
        navigateTo('Login');
        return false;
      }
      showAlert(Util.cleanError(msg), 'error');
    }
  }
  return true;
}

