.hint {
  color: var(--muted);
  font-size: 12px;
  margin-top: 6px;
}

.hint.warn {
  color: var(--danger);
}

.link {
  border: none;
  background: none;
  color: var(--accent);
  font: inherit;
  font-size: 12px;
  font-weight: 600;
  padding: 0;
  cursor: pointer;
}

.link:hover {
  text-decoration: underline;
}

.seg {
  display: flex;
  gap: 8px;
}

.seg button {
  flex: 1;
  height: 38px;
  border: 1px solid var(--border);
  border-radius: var(--radius);
  background: #fff;
  font: inherit;
  font-weight: 600;
  color: var(--text);
  cursor: pointer;
}

.seg button:hover:not(:disabled) {
  background: var(--surface-alt);
}

.seg button.on {
  background: var(--primary);
  border-color: var(--primary);
  color: #fff;
}

.seg.invalid button {
  border-color: var(--danger);
}

.seg button:disabled {
  cursor: not-allowed;
}

.readonly {
  padding: 9px 12px;
  border-radius: var(--radius);
  background: var(--surface-alt);
  color: var(--text);
  min-height: 38px;
}

.check-row {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-top: 16px;
  font-weight: 600;
  cursor: pointer;
}

.check-row input {
  width: 16px;
  height: 16px;
  accent-color: var(--primary);
}

#pendingWarn {
  margin-top: 16px;
}

/* R3: daftar varian (centang banyak) + harga sumber salinan */
.list-head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
}

.list-head .count {
  color: var(--muted);
  font-size: 12px;
  font-weight: 600;
}

.list-tools {
  display: flex;
  align-items: center;
  gap: 12px;
  margin-bottom: 6px;
}

.list-tools input {
  flex: 1;
  height: 32px !important;
}

.vlist {
  border: 1px solid var(--border);
  border-radius: var(--radius);
  max-height: 228px;
  overflow-y: auto;
}

.vrow {
  display: flex;
  align-items: center;
  gap: 10px;
  margin: 0;
  padding: 7px 10px;
  border-bottom: 1px solid var(--surface-alt);
  font-weight: 400;
  font-size: 13px;
  cursor: pointer;
}

.vrow:last-child {
  border-bottom: none;
}

.vrow:hover {
  background: var(--surface-alt);
}

.vrow.on {
  background: var(--info-bg);
}

.vrow.disabled {
  cursor: not-allowed;
  color: var(--muted);
}

.vrow input {
  width: 16px;
  height: 16px;
  flex: none;
  accent-color: var(--primary);
}

.vname {
  flex: 1;
  min-width: 0;
}

.vstat {
  flex: none;
  font-size: 12px;
  text-align: right;
}

.vstat.ok {
  color: #15803D;
}

.vstat.warn {
  color: #B45309;
}

.vstat.muted {
