input:disabled, select:disabled {
  background: var(--surface-alt);
  color: var(--muted);
  cursor: not-allowed;
}

input.invalid, select.invalid {
  border-color: var(--danger);
}

.switch-row {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-top: 16px;
  cursor: pointer;
  font-weight: 600;
}

.switch-row input {
  position: absolute;
  opacity: 0;
  pointer-events: none;
}

.switch {
  width: 38px;
  height: 22px;
  border-radius: 999px;
  background: var(--border);
  position: relative;
  transition: background 0.15s;
  flex: none;
}

.switch::after {
  content: "";
  position: absolute;
  top: 3px;
  left: 3px;
  width: 16px;
  height: 16px;
  border-radius: 50%;
  background: #fff;
  transition: left 0.15s;
  box-shadow: 0 1px 2px rgba(0, 0, 0, 0.2);
}

.switch-row input:checked + .switch {
  background: var(--primary);
}

.switch-row input:checked + .switch::after {
  left: 19px;
}

.switch-row input:disabled + .switch {
  opacity: 0.5;
}

.switch-row input:focus-visible + .switch {
  box-shadow: 0 0 0 3px rgba(59, 111, 224, 0.25);
}

.field-note {
  color: var(--muted);
  font-size: 12px;
  margin-top: 6px;
}

.info {
  background: var(--info-bg);
  color: var(--primary);
  border-radius: var(--radius);
  padding: 10px 12px;
  font-size: 12.5px;
  margin-top: 16px;
}

.msg {
  border-radius: var(--radius);
  padding: 10px 12px;
  font-size: 13px;
  margin-bottom: 4px;
}

.msg.error {
  background: var(--danger-bg);
  color: var(--danger);
}

.msg.info {
  background: var(--info-bg);
  color: var(--primary);
}

.actions {
  display: flex;
  justify-content: flex-end;
  gap: 8px;
  margin-top: 22px;
}

.btn-primary, .btn-secondary {
  height: 38px;
  padding: 0 18px;
  border-radius: var(--radius);
  border: 1px solid transparent;
  font: inherit;
  font-weight: 600;
  cursor: pointer;
}

.btn-primary {
  background: var(--primary);
  color: #fff;
}

.btn-primary:hover:not(:disabled) {
  filter: brightness(1.2);
}

.btn-secondary {
  background: #fff;
  color: var(--text);
  border-color: var(--border);
}

.btn-secondary:hover:not(:disabled) {
  background: var(--surface-alt);
}

button:disabled {
  opacity: 0.6;
  cursor: default;
}

.row {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 12px;
}

.row > div > label {
  margin-top: 14px;
}

input[type=number]::-webkit-inner-spin-button {
  opacity: 0.5;
}

.hint {
  color: var(--muted);
  font-size: 12px;
  margin-top: 6px;
}

.hint.warn {
  color: var(--danger);
}

.link {
  border: none;
  background: none;
  color: var(--accent);
  font: inherit;
  font-size: 12px;
  font-weight: 600;
  padding: 0;
  cursor: pointer;
}

.link:hover {
  text-decoration: underline;
}

.seg {
  display: flex;
  gap: 8px;
}

.seg button {
  flex: 1;
  height: 38px;
  border: 1px solid var(--border);
  border-radius: var(--radius);
  background: #fff;
  font: inherit;
  font-weight: 600;
  color: var(--text);
  cursor: pointer;
}

.seg button:hover:not(:disabled) {
  background: var(--surface-alt);
}

.seg button.on {
  background: var(--primary);
  border-color: var(--primary);
  color: #fff;
}

.seg.invalid button {
  border-color: var(--danger);
}

.seg button:disabled {
  cursor: not-allowed;
}

.readonly {
  padding: 9px 12px;
  border-radius: var(--radius);
  background: var(--surface-alt);
  color: var(--text);
  min-height: 38px;
}

.check-row {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-top: 16px;
  font-weight: 600;
  cursor: pointer;
}

.check-row input {
  width: 16px;
  height: 16px;
  accent-color: var(--primary);
}

#pendingWarn {
  margin-top: 16px;
}

/* R3: daftar varian (centang banyak) + harga sumber salinan */
.list-head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
}

.list-head .count {
  color: var(--muted);
  font-size: 12px;
  font-weight: 600;
}

.list-tools {
  display: flex;
  align-items: center;
  gap: 12px;
  margin-bottom: 6px;
}

.list-tools input {
  flex: 1;
  height: 32px !important;
}

.vlist {
  border: 1px solid var(--border);
  border-radius: var(--radius);
  max-height: 228px;
  overflow-y: auto;
}

.vrow {
  display: flex;
  align-items: center;
  gap: 10px;
  margin: 0;
  padding: 7px 10px;
  border-bottom: 1px solid var(--surface-alt);
  font-weight: 400;
  font-size: 13px;
  cursor: pointer;
}

.vrow:last-child {
  border-bottom: none;
}

.vrow:hover {
  background: var(--surface-alt);
}

.vrow.on {
  background: var(--info-bg);
}

.vrow.disabled {
