  height: 16px;
  flex: none;
  accent-color: var(--primary);
}

.vname {
  flex: 1;
  min-width: 0;
}

.vstat {
  flex: none;
  font-size: 12px;
  text-align: right;
}

.vstat.ok {
  color: #15803D;
}

.vstat.warn {
  color: #B45309;
}

.vstat.muted {
  color: var(--muted);
}

.vlist .empty {
  padding: 12px;
  color: var(--muted);
  font-size: 13px;
}

.src-prices {
  margin-top: 6px;
  color: var(--muted);
  font-size: 12.5px;
  line-height: 1.5;
}

