  cursor: pointer;
}

.btn-primary {
  background: var(--primary);
  color: #fff;
}

.btn-primary:hover:not(:disabled) {
  filter: brightness(1.2);
}

.btn-secondary {
  background: #fff;
  color: var(--text);
  border-color: var(--border);
}

.btn-secondary:hover:not(:disabled) {
  background: var(--surface-alt);
}

button:disabled {
  opacity: 0.6;
  cursor: default;
}

.row {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 12px;
}

.row > div > label {
  margin-top: 14px;
}

input[type=number]::-webkit-inner-spin-button {
  opacity: 0.5;
}

.hint {
  color: var(--muted);
  font-size: 12px;
  margin-top: 6px;
}

.hint.warn {
  color: var(--danger);
}

.link {
  border: none;
  background: none;
  color: var(--accent);
  font: inherit;
  font-size: 12px;
  font-weight: 600;
  padding: 0;
  cursor: pointer;
}

.link:hover {
  text-decoration: underline;
}

.seg {
  display: flex;
  gap: 8px;
}

.seg button {
  flex: 1;
  height: 38px;
  border: 1px solid var(--border);
  border-radius: var(--radius);
  background: #fff;
  font: inherit;
  font-weight: 600;
  color: var(--text);
  cursor: pointer;
}

.seg button:hover:not(:disabled) {
  background: var(--surface-alt);
}

.seg button.on {
  background: var(--primary);
  border-color: var(--primary);
  color: #fff;
}

.seg.invalid button {
  border-color: var(--danger);
}

.seg button:disabled {
  cursor: not-allowed;
}

.readonly {
  padding: 9px 12px;
  border-radius: var(--radius);
  background: var(--surface-alt);
  color: var(--text);
  min-height: 38px;
}

.check-row {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-top: 16px;
  font-weight: 600;
  cursor: pointer;
}

.check-row input {
  width: 16px;
  height: 16px;
  accent-color: var(--primary);
}

/* R2b: cwVariantForm - peringatan awalan kode */
.warn-box {
  margin-top: 8px;
  border: 1px solid #F1D9A6;
  background: #FFF8E6;
  color: #8A5A00;
  border-radius: var(--radius);
  padding: 8px 12px;
  font-size: 12.5px;
}

/* R9: usulan Material Code */
.sug {
  margin-top: 8px;
  border: 1px solid var(--border, #D6DCE8);
  background: #F5F8FE;
  border-radius: var(--radius);
  padding: 8px 12px;
  font-size: 12.5px;
  color: #33415C;
}

.sug-row {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 6px;
  margin-top: 4px;
}

.sug-label {
  min-width: 112px;
  color: #6B7280;
}

.sug-code {
  font-family: Consolas, "Courier New", monospace;
  font-weight: 600;
}

.sug-none {
  color: #8A5A00;
}

.sug-other {
  color: #6B7280;
}

/* R9: konfirmasi arti kode. R20: kotak merah = masalah aturan kode (tanpa centang) + tombol Use */
.conf-box {
  margin-top: 8px;
  border: 1px solid #F3B7B0;
  background: #FDEDEB;
  color: #9B2C1F;
  border-radius: var(--radius);
  padding: 8px 12px;
  font-size: 12.5px;
}

.use-row {
  margin-top: 8px;
}

