  display: flex;
  align-items: center;
  gap: 10px;
  margin-top: 16px;
  cursor: pointer;
  font-weight: 600;
}

.switch-row input {
  position: absolute;
  opacity: 0;
  pointer-events: none;
}

.switch {
  width: 38px;
  height: 22px;
  border-radius: 999px;
  background: var(--border);
  position: relative;
  transition: background 0.15s;
  flex: none;
}

.switch::after {
  content: "";
  position: absolute;
  top: 3px;
  left: 3px;
  width: 16px;
  height: 16px;
  border-radius: 50%;
  background: #fff;
  transition: left 0.15s;
  box-shadow: 0 1px 2px rgba(0, 0, 0, 0.2);
}

.switch-row input:checked + .switch {
  background: var(--primary);
}

.switch-row input:checked + .switch::after {
  left: 19px;
}

.switch-row input:disabled + .switch {
  opacity: 0.5;
}

.switch-row input:focus-visible + .switch {
  box-shadow: 0 0 0 3px rgba(59, 111, 224, 0.25);
}

.field-note {
  color: var(--muted);
  font-size: 12px;
  margin-top: 6px;
}

.info {
  background: var(--info-bg);
  color: var(--primary);
  border-radius: var(--radius);
  padding: 10px 12px;
  font-size: 12.5px;
  margin-top: 16px;
}

.msg {
