  background: var(--surface-alt);
}

button:disabled {
  opacity: 0.6;
  cursor: default;
}

.row {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 12px;
}

.row > div > label {
  margin-top: 14px;
}

input[type=number]::-webkit-inner-spin-button {
  opacity: 0.5;
}

.hint {
  color: var(--muted);
  font-size: 12px;
  margin-top: 6px;
}

.hint.warn {
  color: var(--danger);
}

.link {
