  color: var(--accent);
  font: inherit;
  font-size: 12px;
  font-weight: 600;
  padding: 0;
  cursor: pointer;
}

.link:hover {
  text-decoration: underline;
}

.seg {
  display: flex;
  gap: 8px;
}

.seg button {
  flex: 1;
  height: 38px;
  border: 1px solid var(--border);
  border-radius: var(--radius);
  background: #fff;
  font: inherit;
  font-weight: 600;
  color: var(--text);
  cursor: pointer;
}

.seg button:hover:not(:disabled) {
  background: var(--surface-alt);
}

.seg button.on {
  background: var(--primary);
  border-color: var(--primary);
  color: #fff;
}

.seg.invalid button {
  border-color: var(--danger);
}

.seg button:disabled {
  cursor: not-allowed;
}

.readonly {
  padding: 9px 12px;
  border-radius: var(--radius);
  background: var(--surface-alt);
  color: var(--text);
  min-height: 38px;
}

.check-row {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-top: 16px;
  font-weight: 600;
  cursor: pointer;
}

.check-row input {
  width: 16px;
  height: 16px;
  accent-color: var(--primary);
}

/* R2b: cwVariantForm - peringatan awalan kode */
.warn-box {
  margin-top: 8px;
  border: 1px solid #F1D9A6;
  background: #FFF8E6;
  color: #8A5A00;
  border-radius: var(--radius);
  padding: 8px 12px;
  font-size: 12.5px;
}

/* R9: usulan Material Code */
.sug {
  margin-top: 8px;
  border: 1px solid var(--border, #D6DCE8);
  background: #F5F8FE;
  border-radius: var(--radius);
  padding: 8px 12px;
  font-size: 12.5px;
  color: #33415C;
}

.sug-row {
  display: flex;
