}

.sug-code {
  font-family: Consolas, "Courier New", monospace;
  font-weight: 600;
}

.sug-none {
  color: #8A5A00;
}

.sug-other {
  color: #6B7280;
}

/* R9: konfirmasi arti kode. R20: kotak merah = masalah aturan kode (tanpa centang) + tombol Use */
.conf-box {
  margin-top: 8px;
  border: 1px solid #F3B7B0;
  background: #FDEDEB;
  color: #9B2C1F;
  border-radius: var(--radius);
  padding: 8px 12px;
  font-size: 12.5px;
}

.use-row {
  margin-top: 8px;
}

