:root {
  --primary: #122A52;
  --accent: #3B6FE0;
  --surface: #FFFFFF;
  --surface-alt: #EEF1F7;
  --text: #1B2333;
  --muted: #6B7280;
  --border: #D6DCE8;
  --danger: #C0392B;
  --danger-bg: #FDEDEB;
  --info-bg: #DCE4F3;
  --radius: 8px;
  --font: "Segoe UI", -apple-system, BlinkMacSystemFont, Roboto, Helvetica, Arial, sans-serif;
}

* {
  box-sizing: border-box;
}

html, body {
  margin: 0;
  height: 100%;
  background: var(--surface);
}

body {
  color: var(--text);
  font-family: var(--font);
  font-size: 14px;
}

[hidden] {
  display: none !important;
}

.wrap {
  padding: 20px 24px;
}

.head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 12px;
}

h2 {
  margin: 0;
  font-size: 18px;
}

.x {
  border: none;
  background: none;
  font-size: 16px;
  color: var(--muted);
  cursor: pointer;
  padding: 4px 8px;
  border-radius: var(--radius);
}

.x:hover {
  background: var(--surface-alt);
}

label {
  display: block;
  font-weight: 600;
  font-size: 12.5px;
  margin: 14px 0 6px;
}

.req {
  color: var(--danger);
}

input[type=text], input[type=email], input[type=number], select {
  width: 100%;
  height: 38px;
  padding: 0 12px;
  border: 1px solid var(--border);
  border-radius: var(--radius);
  font: inherit;
  color: inherit;
  background: #fff;
}

input:focus, select:focus {
  outline: none;
  border-color: var(--accent);
  box-shadow: 0 0 0 3px rgba(59, 111, 224, 0.18);
}

input:disabled, select:disabled {
  background: var(--surface-alt);
  color: var(--muted);
  cursor: not-allowed;
}

input.invalid, select.invalid {
  border-color: var(--danger);
}

.switch-row {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-top: 16px;
  cursor: pointer;
  font-weight: 600;
}

.switch-row input {
  position: absolute;
  opacity: 0;
  pointer-events: none;
}

.switch {
  width: 38px;
  height: 22px;
  border-radius: 999px;
  background: var(--border);
  position: relative;
  transition: background 0.15s;
  flex: none;
}

.switch::after {
  content: "";
  position: absolute;
  top: 3px;
  left: 3px;
  width: 16px;
  height: 16px;
  border-radius: 50%;
  background: #fff;
  transition: left 0.15s;
  box-shadow: 0 1px 2px rgba(0, 0, 0, 0.2);
}

.switch-row input:checked + .switch {
  background: var(--primary);
}

.switch-row input:checked + .switch::after {
  left: 19px;
}

.switch-row input:disabled + .switch {
  opacity: 0.5;
