:root {
  --primary: #122A52;
  --accent: #3B6FE0;
  --bg: #F3F5FA;
  --surface: #FFFFFF;
  --surface-alt: #EEF1F7;
  --text: #1B2333;
  --muted: #6B7280;
  --border: #D6DCE8;
  --info-bg: #DCE4F3;
  --warn: #B45309;
  --warn-bg: #FEF3C7;
  --danger: #C0392B;
  --danger-bg: #FDEDEB;
  --ok: #15803D;
  --ok-bg: #DCFCE7;
  --radius: 8px;
  --font: "Segoe UI", -apple-system, BlinkMacSystemFont, Roboto, Helvetica, Arial, sans-serif;
}

* {
  box-sizing: border-box;
}

html, body {
  margin: 0;
}

body {
  font-family: var(--font);
  font-size: 14px;
  color: var(--text);
  background: var(--bg);
}

[hidden] {
  display: none !important;
}

.wrap {
  padding: 20px 24px 16px;
}

.head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 14px;
}

.head h2 {
  font-size: 17px;
  margin: 0;
}

.head p {
  margin: 4px 0 0;
  color: var(--muted);
  font-size: 13px;
}

.btn {
  flex: none;
  height: 32px;
  padding: 0 14px;
  border: 1px solid var(--border);
  border-radius: var(--radius);
  background: var(--surface);
  color: var(--primary);
  font: inherit;
  font-size: 13px;
  font-weight: 600;
  cursor: pointer;
}

.btn:hover:not(:disabled) {
  border-color: var(--accent);
}

.btn:disabled {
  opacity: 0.55;
  cursor: default;
}

.btn.primary {
  background: var(--primary);
  border-color: var(--primary);
  color: #fff;
}

.btn.danger {
  color: var(--danger);
}

.btn.danger.solid {
  background: var(--danger);
  border-color: var(--danger);
  color: #fff;
}

.btn.armed {
  background: var(--warn);
  border-color: var(--warn);
  color: #fff;
}

.msg {
  border-radius: var(--radius);
  padding: 10px 12px;
  font-size: 13px;
  margin-bottom: 12px;
}

.msg.error {
  background: var(--danger-bg);
  color: var(--danger);
}

.msg.success {
  background: var(--ok-bg);
  color: var(--ok);
}

.msg.info {
  background: var(--info-bg);
  color: var(--primary);
}

.batches {
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.card {
  padding: 16px 18px;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: calc(var(--radius) * 1.25);
  box-shadow: 0 1px 2px rgba(16, 24, 40, 0.05);
}

.card.focus {
  border-color: var(--accent);
  box-shadow: 0 0 0 3px rgba(59, 111, 224, 0.15);
}

.card.skeleton {
  height: 160px;
  background: linear-gradient(90deg, var(--surface) 0%, var(--surface-alt) 50%, var(--surface) 100%);
}

.card-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 12px;
}

.card-head h3 {
  margin: 0;
  font-size: 15px;
  color: var(--primary);
}

.card-head .meta {
  margin-top: 4px;
  color: var(--muted);
  font-size: 12.5px;
}

.link {
  border: none;
  background: none;
  color: var(--accent);
  font: inherit;
  font-size: 12.5px;
  font-weight: 600;
  padding: 0;
  cursor: pointer;
  white-space: nowrap;
}

.link:hover {
  text-decoration: underline;
}

.table-wrap {
  overflow-x: auto;
  margin-top: 12px;
}

table {
  width: 100%;
  border-collapse: collapse;
  font-size: 13px;
}

th, td {
  padding: 7px 8px;
  border-bottom: 1px solid var(--surface-alt);
  text-align: left;
  white-space: nowrap;
}

th {
  color: var(--muted);
  font-size: 12px;
  font-weight: 600;
  background: var(--surface-alt);
}

td.num, th.num {
  text-align: right;
}

tr.sel td {
  background: var(--info-bg);
}

tr.bad td {
  color: var(--muted);
}

td input[type=checkbox], th input[type=checkbox] {
  width: 16px;
  height: 16px;
  accent-color: var(--primary);
  cursor: pointer;
}

.up {
  color: var(--danger);
  font-weight: 600;
}

.down {
  color: var(--ok);
  font-weight: 600;
}

.badge {
  display: inline-block;
  padding: 1px 8px;
  border-radius: 999px;
  background: var(--danger-bg);
  color: var(--danger);
  font-size: 11.5px;
  font-weight: 600;
}

.ref {
  max-width: 180px;
  overflow: hidden;
  text-overflow: ellipsis;
}

.actions {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: flex-end;
  gap: 8px;
  margin-top: 12px;
}

.actions .hint {
  margin-right: auto;
  color: var(--muted);
  font-size: 12.5px;
}

.reject {
  margin-top: 12px;
  padding: 12px;
  border-radius: var(--radius);
  background: var(--danger-bg);
}

.reject label {
  display: block;
  font-weight: 600;
  font-size: 12.5px;
  margin-bottom: 6px;
  color: var(--danger);
}

.reject textarea {
  width: 100%;
  min-height: 60px;
  padding: 8px 10px;
  border: 1px solid var(--border);
  border-radius: var(--radius);
  font: inherit;
  resize: vertical;
}

.reject .actions {
  margin-top: 8px;
}

.empty {
  padding: 32px;
  text-align: center;
  color: var(--muted);
  background: var(--surface);
  border: 1px dashed var(--border);
  border-radius: var(--radius);
}

