:root {
  --primary: #122A52;
  --accent: #3B6FE0;
  --bg: #F3F5FA;
  --surface: #FFFFFF;
  --surface-alt: #EEF1F7;
  --text: #1B2333;
  --muted: #6B7280;
  --border: #D6DCE8;
  --info-bg: #DCE4F3;
  --warn: #B45309;
  --warn-bg: #FEF3C7;
  --danger: #C0392B;
  --danger-bg: #FDEDEB;
  --ok: #15803D;
  --ok-bg: #DCFCE7;
  --radius: 8px;
  --font: "Segoe UI", -apple-system, BlinkMacSystemFont, Roboto, Helvetica, Arial, sans-serif;
}

* {
  box-sizing: border-box;
}

html, body {
  margin: 0;
}

body {
  font-family: var(--font);
  font-size: 14px;
  color: var(--text);
  background: var(--bg);
}

[hidden] {
  display: none !important;
}

.wrap {
  padding: 20px 24px 16px;
}

.head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 14px;
}

.head h2 {
  font-size: 17px;
  margin: 0;
}

.head p {
  margin: 4px 0 0;
  color: var(--muted);
  font-size: 13px;
}

.btn {
  flex: none;
  height: 32px;
  padding: 0 14px;
  border: 1px solid var(--border);
  border-radius: var(--radius);
  background: var(--surface);
  color: var(--primary);
  font: inherit;
  font-size: 13px;
  font-weight: 600;
  cursor: pointer;
}

.btn:hover:not(:disabled) {
  border-color: var(--accent);
}

.btn:disabled {
  opacity: 0.55;
  cursor: default;
}

.btn.primary {
  background: var(--primary);
  border-color: var(--primary);
  color: #fff;
}

.btn.danger {
  color: var(--danger);
}

.btn.danger.solid {
  background: var(--danger);
  border-color: var(--danger);
  color: #fff;
}

.btn.armed {
  background: var(--warn);
  border-color: var(--warn);
  color: #fff;
}

.msg {
  border-radius: var(--radius);
  padding: 10px 12px;
  font-size: 13px;
  margin-bottom: 12px;
}

.msg.error {
  background: var(--danger-bg);
  color: var(--danger);
}

.msg.success {
  background: var(--ok-bg);
  color: var(--ok);
}

.msg.info {
  background: var(--info-bg);
  color: var(--primary);
}

.batches {
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.card {
  padding: 16px 18px;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: calc(var(--radius) * 1.25);
  box-shadow: 0 1px 2px rgba(16, 24, 40, 0.05);
}

.card.focus {
