:root {
  --primary: #122A52;
  --primary-light: #1F3E70;
  --soft: #DCE4F3;
  --radius: 8px;
  --font: "Segoe UI", -apple-system, BlinkMacSystemFont, Roboto, Helvetica, Arial, sans-serif;
}

* { box-sizing: border-box; }
html, body { margin: 0; height: 100%; }
body { font-family: var(--font); font-size: 14px; background: var(--primary); overflow: hidden; }
[hidden] { display: none !important; }

.bar {
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
  padding: 0 24px;
  background: linear-gradient(90deg, var(--primary) 0%, var(--primary-light) 100%);
  color: #fff;
}

.left { display: flex; align-items: center; gap: 12px; min-width: 0; }
.logo {
  width: 40px; height: 40px; flex: none;
  border-radius: var(--radius);
  background: #fff; color: var(--primary);
  font-weight: 800; letter-spacing: .5px;
  display: flex; align-items: center; justify-content: center;
}
.titles { min-width: 0; }
.app { font-weight: 700; font-size: 15px; white-space: nowrap; }
.page { color: var(--soft); font-size: 12.5px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }

.right { display: flex; align-items: center; gap: 10px; flex: none; }

.user { display: flex; align-items: center; gap: 10px; }
.avatar {
  width: 36px; height: 36px; border-radius: 50%;
  background: rgba(255,255,255,.18); border: 1px solid rgba(255,255,255,.35);
  display: flex; align-items: center; justify-content: center;
  font-weight: 700; font-size: 13px;
}
.who { line-height: 1.25; }
.name { font-weight: 600; max-width: 220px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.chip {
  display: inline-block; margin-top: 2px;
  padding: 1px 8px; border-radius: 999px;
  background: rgba(255,255,255,.16); color: var(--soft);
  font-size: 11.5px; font-weight: 600;
}

.sep { width: 1px; height: 32px; background: rgba(255,255,255,.25); margin: 0 4px; }

button {
  height: 34px; padding: 0 14px;
  border-radius: var(--radius);
  font: inherit; font-weight: 600; font-size: 13px;
  cursor: pointer; display: inline-flex; align-items: center; gap: 6px;
  white-space: nowrap;
}
.btn-ghost { background: transparent; color: #fff; border: 1px solid rgba(255,255,255,.4); }
.btn-ghost:hover { background: rgba(255,255,255,.12); }
.btn-light { background: #fff; color: var(--primary); border: 1px solid #fff; }
.btn-light:hover { background: var(--soft); }
.ico { font-size: 13px; line-height: 1; }

