  margin-bottom: 12px;
}

h2 {
  margin: 0;
  font-size: 18px;
}

.x {
  border: none;
  background: none;
  font-size: 16px;
  color: var(--muted);
  cursor: pointer;
  padding: 4px 8px;
  border-radius: var(--radius);
}

.x:hover {
  background: var(--surface-alt);
}

label {
  display: block;
  font-weight: 600;
  font-size: 12.5px;
  margin: 14px 0 6px;
}

.req {
  color: var(--danger);
}

input[type=text], input[type=email], input[type=number], input[type=date], select {
  width: 100%;
  height: 38px;
  padding: 0 12px;
  border: 1px solid var(--border);
  border-radius: var(--radius);
  font: inherit;
  color: inherit;
  background: #fff;
}

input:focus, select:focus {
  outline: none;
  border-color: var(--accent);
  box-shadow: 0 0 0 3px rgba(59, 111, 224, 0.18);
