  border-radius: var(--radius);
  padding: 10px 12px;
  font-size: 12.5px;
  margin-top: 16px;
}

.msg {
  border-radius: var(--radius);
  padding: 10px 12px;
  font-size: 13px;
  margin-bottom: 4px;
