.step {
  flex: 1;
  min-width: 0;
  position: relative;
  padding: 8px 12px 8px 20px;
  border: 1px solid var(--border);
  border-left: none;
  background: var(--surface-alt);
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.step:first-child {
  border-left: 1px solid var(--border);
  border-radius: var(--radius) 0 0 var(--radius);
