}

.step:last-child {
  border-radius: 0 var(--radius) var(--radius) 0;
}

.step.has-revs {
  background: var(--surface);
}

.step.current {
  box-shadow: inset 0 -3px 0 var(--primary);
}

.stage {
  font-weight: 700;
  font-size: 12px;
  letter-spacing: 0.04em;
  color: var(--muted);
}

.step.has-revs .stage {
  color: var(--primary);
}

.chips {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  min-height: 26px;
  align-items: center;
}

.none {
  color: var(--muted);
}

.chip {
  height: 26px;
  min-width: 36px;
  padding: 0 10px;
  border-radius: 999px;
  border: 1px solid var(--primary);
  background: var(--surface);
  color: var(--primary);
  font: inherit;
  font-weight: 600;
  cursor: pointer;
}

.chip:hover {
  background: var(--surface-alt);
}

.chip.draft {
  border-color: var(--draft);
  color: var(--draft);
  background: var(--draft-bg);
  border-style: dashed;
}

.chip.active {
  background: var(--primary);
  color: #fff;
  border-style: solid;
  border-color: var(--primary);
}

.chip.draft.active {
  background: var(--draft);
  border-color: var(--draft);
}

.chip:focus-visible {
  outline: none;
  box-shadow: 0 0 0 3px rgba(59, 111, 224, 0.3);
}

.empty {
  color: var(--muted);
  padding: 0 4px;
}

.chip.needs {
  border-color: var(--danger);
  color: var(--danger);
}

.chip.needs.active {
  background: var(--danger);
  border-color: var(--danger);
  color: #fff;
}

.arts {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  align-items: center;
}

.art {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  height: 32px;
  padding: 0 10px;
  border: 1px solid var(--border);
  border-radius: var(--radius);
  background: var(--surface);
  color: var(--text);
