  cursor: pointer;
}

.art:hover {
  background: var(--surface-alt);
}

.art.active {
  border-color: var(--primary);
  box-shadow: 0 0 0 1px var(--primary);
}

.art:focus-visible {
  outline: none;
  box-shadow: 0 0 0 3px rgba(59, 111, 224, 0.3);
