  color: var(--muted);
  border: 1px solid var(--border);
  border-radius: 4px;
  padding: 0 4px;
}

.ro {
  display: block;
  padding: 5px 0;
  white-space: normal;
  word-break: break-word;
}

.none {
  color: var(--muted);
}

.code {
  display: block;
  font-size: 11px;
  color: var(--muted);
}

.code.nocode {
  display: inline-block;
  margin-top: 2px;
  padding: 0 5px;
  border-radius: 4px;
  background: #FFF3B0;
  color: #7A5B00;
