input.cell {
  width: 100%;
  height: 28px;
  padding: 0 6px;
  border: 1px solid var(--border);
  border-radius: 4px;
  font: inherit;
  color: inherit;
  background: #fff;
  text-align: right;
}

input.cell:focus {
  outline: none;
  border-color: var(--accent);
  box-shadow: 0 0 0 2px rgba(59, 111, 224, 0.18);
}

input.cell.invalid {
