  background: var(--danger-bg);
}

input.cell.need {
  border-color: var(--warn);
  background: var(--warn-bg);
}

.badge {
  display: inline-block;
  margin-top: 2px;
  font-size: 10.5px;
  font-weight: 600;
  border-radius: 4px;
  padding: 0 5px;
}

.badge.master { background: var(--info-bg); color: var(--primary); }
.badge.override, .badge.quotation { background: var(--warn-bg); color: var(--warn); }
.badge.estimate { background: #FFF3B0; color: #7A5B00; border: 1px solid #E8C547; }   /* R17: kuning seperti sel tanpa kode */
.badge.nocharge { background: var(--surface-alt); color: var(--muted); border: 1px dashed var(--border); }

/* R11: form alasan Tanpa biaya di sel Harga */
.ncform {
  margin-top: 4px;
  display: flex;
  flex-direction: column;
  gap: 4px;
  min-width: 190px;
}

.ncbtns {
  display: flex;
  justify-content: flex-end;
  align-items: center;
  gap: 10px;
}

.bbtn.sm {
  height: 24px;
  padding: 0 10px;
  font-size: 11.5px;
}
.hint {
  display: block;
  font-size: 11px;
  color: var(--muted);
  white-space: normal;
  text-align: right;
}

.hint.warn {
  color: var(--warn);
}

.empty {
  color: var(--muted);
  padding: 16px 8px;
}

/* ---------------------------------------------------------------- F8: harga, banner, rekap */
.acts {
  margin-top: 2px;
  display: flex;
  flex-wrap: wrap;
  justify-content: flex-end;
  gap: 2px 10px;
}

.lnk {
  border: none;
  background: none;
  padding: 0;
  font: inherit;
  font-size: 11.5px;
  font-weight: 600;
  color: var(--accent);
  cursor: pointer;
}

.lnk:hover:not(:disabled) {
  text-decoration: underline;
}

.lnk.danger {
  color: var(--danger);
}

.lnk:disabled, .bbtn:disabled {
  opacity: 0.5;
  cursor: default;
}

.banners {
  flex: none;
  display: flex;
  flex-direction: column;
  gap: 6px;
  padding: 0 8px 6px;
}

.banner {
  display: flex;
  align-items: center;
  gap: 12px;
  border-radius: var(--radius);
  padding: 6px 10px;
  font-size: 12.5px;
}

.banner.danger { background: var(--danger-bg); color: var(--danger); }
.banner.warn { background: var(--warn-bg); color: var(--warn); }
.banner.info { background: var(--info-bg); color: var(--primary); }

.banner .btext {
  flex: 1;
}

.bbtn {
  flex: none;
  height: 28px;
  padding: 0 12px;
  border: none;
  border-radius: var(--radius);
  background: var(--primary);
  color: #fff;
  font: inherit;
  font-size: 12px;
  font-weight: 600;
  cursor: pointer;
}

.recap {
  flex: none;
  display: grid;
  grid-template-columns: repeat(9, minmax(110px, 1fr));
  gap: 8px;
  padding: 8px;
