/* ---------------------------------------------------------------- F8b: subtotal, tabel bawah */
tr.subtotal td {
  background: #F7F9FC;
  font-weight: 700;
  color: var(--primary);
  border-bottom: 2px solid var(--border);
}

tr.subtotal .glabel {
