  margin: 0;
  height: 100%;
  background: var(--surface);
}

body {
  color: var(--text);
  font-family: var(--font);
  font-size: 14px;
}

[hidden] {
  display: none !important;
}

.wrap {
  padding: 20px 24px;
}

.head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 12px;
}

h2 {
  margin: 0;
  font-size: 18px;
}

.x {
  border: none;
  background: none;
  font-size: 16px;
  color: var(--muted);
  cursor: pointer;
  padding: 4px 8px;
  border-radius: var(--radius);
}

.x:hover {
  background: var(--surface-alt);
}

label {
  display: block;
  font-weight: 600;
  font-size: 12.5px;
  margin: 14px 0 6px;
}

.req {
  color: var(--danger);
}

input[type=text], input[type=email], input[type=number], input[type=date], select {
  width: 100%;
  height: 38px;
  padding: 0 12px;
