  background: #FFF3B0;
  color: #7A5B00;
  font-size: 12.5px;
}

.lnk {
  border: none;
  background: none;
  padding: 0 0 0 6px;
  color: var(--accent);
  font: inherit;
  font-weight: 600;
  cursor: pointer;
}

.lnk:hover:not(:disabled) {
  text-decoration: underline;
}

.current {
  margin-top: 12px;
  padding: 10px 12px;
  border-radius: var(--radius);
  background: var(--surface-alt);
  font-size: 12.5px;
}

textarea {
  width: 100%;
  min-height: 72px;
  padding: 8px 12px;
  border: 1px solid var(--border);
  border-radius: var(--radius);
  font: inherit;
  color: inherit;
  resize: vertical;
}

textarea:focus {
  outline: none;
  border-color: var(--accent);
  box-shadow: 0 0 0 3px rgba(59, 111, 224, 0.18);
}

textarea.invalid {
  border-color: var(--danger);
}

