// ---------------------------------------------------------------- tabel bawah (F8b)
function cell(tag, cls, child) {
  const c = el(tag, cls);
  if (child === undefined || child === null) return c;
  if (typeof child === 'string') c.textContent = child;
  else c.appendChild(child);
  return c;
}

