async function () {
  const mode = appsmith.URL.queryParams.mode;
  LoginCtrl.view = 'login';
  LoginCtrl.busy = false;
  LoginCtrl.forced = false;
  LoginCtrl.setMessage(null);
  LoginCtrl.lastEmail = appsmith.store.lastEmail || LoginCtrl.lastEmail;
  if (appsmith.store.doLogout) {
    await removeValue('doLogout');
    await LoginCtrl.logout();
    return;
  }
  if (!appsmith.store.token) return;
  const me = await LoginCtrl.loadMe();
  if (!me) {
    await removeValue('token');
    return;
  }
  if (me.must_change_password || mode === 'ganti') {
    LoginCtrl.openChange(me.must_change_password);
    return;
  }
  LoginCtrl.goHome();
}

