actionConfiguration.body:
async function () {
  const m = cwUserForm.model || ({});
  const needsFactory = AdminCtrl.factoryRoles.includes(m.role);
  const data = {
    email: String(m.email || '').trim().toLowerCase(),
    full_name: String(m.full_name || '').trim(),
    role: m.role,
    is_active: m.is_active !== false,
    is_new: AdminCtrl.isNew,
    factory_id: needsFactory ? m.factory_id || '' : ''
  };
  if (!data.email || !data.full_name || !data.role) {
    AdminCtrl.message = {
      type: 'error',
      text: 'Fill in email, name, and role.'
    };
    return;
  }
  if (needsFactory && !data.factory_id) {
    AdminCtrl.message = {
      type: 'error',
      text: 'This role needs a factory.'
    };
    return;
  }
  AdminCtrl.message = null;
  AdminCtrl.busy = true;
  try {
    await a_user_save.run(data);
  } catch (e) {
    const msg = e && e.message;
    if (Util.isSessionError(msg)) {
      closeModal('mdlUser');
      await removeValue('token');
      showAlert('Session expired. Please log in again.', 'warning');
      navigateTo('Login');
      return;
    }
    AdminCtrl.message = {
      type: 'error',
      text: Util.cleanError(msg)
    };
    return;
  } finally {
    AdminCtrl.busy = false;
  }
  closeModal('mdlUser');
  showAlert('User saved.', 'success');
  for (const q of [q_users, q_factories, q_audit, q_audit_entities]) {
    try {
      await q.run();
    } catch (e) {}
  }
  const pass = a_user_save.data && a_user_save.data[0] && a_user_save.data[0].temp_password;
  if (pass) AdminCtrl.showTempPassword(data.email, pass);
}

