actionConfiguration.body:
async function () {
  const m = cwFactoryForm.model || ({});
  const data = {
    id: AdminCtrl.factoryForm.id || '',
    name: String(m.name || '').trim(),
    status: m.status || 'ACTIVE'
  };
  if (!data.name) {
    AdminCtrl.factoryMessage = {
      type: 'error',
      text: 'Factory name is required.'
    };
    return;
  }
  AdminCtrl.factoryMessage = null;
  AdminCtrl.factoryBusy = true;
  try {
    await a_factory_save.run(data);
  } catch (e) {
    const msg = e && e.message;
    if (Util.isSessionError(msg)) {
      closeModal('mdlPabrik');
      await removeValue('token');
      showAlert('Session expired. Please log in again.', 'warning');
      navigateTo('Login');
      return;
    }
    AdminCtrl.factoryMessage = {
      type: 'error',
      text: Util.cleanError(msg)
    };
    return;
  } finally {
    AdminCtrl.factoryBusy = false;
  }
  closeModal('mdlPabrik');
  showAlert('Factory saved.', 'success');
  for (const q of [q_factories, q_users, q_audit, q_audit_entities]) {
    try {
      await q.run();
    } catch (e) {}
  }
}

