actionConfiguration.body:
function (id) {
  const row = (q_audit.data || []).find(r => String(r.id) === String(id));
  if (!row) return {
    empty: true
  };
  const before = AdminCtrl.auditJson(row.before_data);
  const after = AdminCtrl.auditJson(row.after_data);
  const action = String(row.action || '');
  let keys = [...new Set([...Object.keys(before || ({})), ...Object.keys(after || ({}))])];
  if (action === 'UPDATE' && before && after) {
    keys = keys.filter(k => JSON.stringify(before[k]) !== JSON.stringify(after[k]));
  }
  const secret = new RegExp(AdminCtrl.auditSecret, 'i');
  keys = keys.filter(k => !secret.test(k)).sort();
  const kind = action === 'UPDATE' ? 'diff' : action === 'DELETE' ? 'before' : action === 'INSERT' ? 'after' : 'diff';
  const rows = keys.map(k => ({
    field: k,
    tech: AdminCtrl.auditTechKeys.includes(k),
    before: kind === 'after' ? null : AdminCtrl.auditValue(before ? before[k] : null),
    after: kind === 'before' ? null : AdminCtrl.auditValue(after ? after[k] : null)
  }));
  let note = '';
  if (!rows.length) {
    note = action === 'INSERT' ? 'Record created. New records are not copied to the audit log.' : action === 'UPDATE' ? 'No changed fields recorded.' : 'No data recorded for this action.';
  }
  return {
    empty: false,
    key: row.id,
    action,
    entity: row.entity || '-',
    entityId: row.entity_id || '-',
    time: row.created_at ? moment(row.created_at).utcOffset(7).format('DD MMM YYYY, HH:mm:ss') + ' WIB' : '-',
    user: row.user_email || '-',
    kind,
    title: ({
      UPDATE: 'Changed fields',
      DELETE: 'Deleted record',
      INSERT: 'Created record'
    })[action] || 'Data',
    note,
    rows
  };
}

