async function () {
  const text = String((cwKomponenForm.model || ({})).similarQuery || '').trim();
  const seq = KomponenCtrl.similarSeq + 1;
  KomponenCtrl.similarSeq = seq;
  if (text.length < 2) {
    KomponenCtrl.similar = [];
    KomponenCtrl.similarFor = text;
    return;
  }
  try {
    const rows = await q_similar.run({
      kind: 'COMPONENT',
      text,
      exclude_id: KomponenCtrl.form.id || ''
    });
    if (seq !== KomponenCtrl.similarSeq) return;
    KomponenCtrl.similar = rows || [];
    KomponenCtrl.similarFor = text;
  } catch (e) {}
}

