async function () {
		const f = cwLinkForm.model || {};
		const params = {
			link_id: MaterialDetailCtrl.linkIsNew ? null : MaterialDetailCtrl.linkForm.id,
			material_id: appsmith.URL.queryParams.id,
			supplier_id: MaterialDetailCtrl.linkIsNew ? f.supplier_id : MaterialDetailCtrl.linkForm.supplier_id,
			is_preferred: !!f.is_preferred,
			status: MaterialDetailCtrl.linkIsNew ? 'ACTIVE' : f.status,
		};
		const ok = await MaterialDetailCtrl.runForm(a_link_save, params,
			v => { MaterialDetailCtrl.linkMsg = v; }, v => { MaterialDetailCtrl.linkBusy = v; }, 'mdlLink');
		if (!ok) return;
		closeModal('mdlLink');
		showAlert(MaterialDetailCtrl.linkIsNew ? 'Material supplier added.' : 'Material supplier saved.', 'success');
		await MaterialDetailCtrl.refresh([q_links, q_link_supplier_options, q_material]);
	}

