actionConfiguration.body:
async function () {
		const f = cwPriceForm.model || {};
		const ids = Array.isArray(f.variant_ids) ? f.variant_ids : [];
		const copy = f.mode === 'copy';
		if (!ids.length || !f.valid_from || (copy ? !f.source_id : (!f.link_id || !f.price || !f.currency))) {
			MaterialDetailCtrl.priceMsg = { type: 'error', text: 'Fill in the required fields.' };
			return;
		}
		const query = copy ? a_price_copy : a_price_propose;
		const params = copy
			? { source_id: f.source_id, variant_ids: JSON.stringify(ids), valid_from: f.valid_from, reference: f.reference }
			: {
				link_id: f.link_id, variant_ids: JSON.stringify(ids), price: f.price, currency: f.currency,
				valid_from: f.valid_from, reference: f.reference,
			};
		const ok = await MaterialDetailCtrl.runForm(query, params,
			v => { MaterialDetailCtrl.priceMsg = v; }, v => { MaterialDetailCtrl.priceBusy = v; }, 'mdlHarga');
		if (!ok) return;
		const result = (query.data && query.data[0]) || {};
		closeModal('mdlHarga');
		const done = MaterialDetailCtrl.canApprovePrice() ? 'saved and active now' : 'proposed, waiting for Manager Costing approval';
		if (copy) {
			showAlert(`${result.created || 0} price(s) ${done}.`
				+ (result.skipped ? ` Skipped: ${result.skipped}` : ''), result.skipped ? 'warning' : 'success');
		} else {
			showAlert(`${ids.length} price(s) ${done}.`, 'success');
		}
		await MaterialDetailCtrl.refresh([q_prices, q_material]);
	}

