actionConfiguration.body:
async function () {
		const f = cwVariantForm.model || {};
		const isNew = MaterialDetailCtrl.varIsNew;
		const params = {
			id: isNew ? '' : MaterialDetailCtrl.varForm.id, material_id: appsmith.URL.queryParams.id,
			code: f.code, color: f.color, thickness: f.thickness, status: isNew ? 'ACTIVE' : f.status,
		};
		const ok = await MaterialDetailCtrl.runForm(a_variant_save, params,
			v => { MaterialDetailCtrl.varMsg = v; }, v => { MaterialDetailCtrl.varBusy = v; }, 'mdlVarian');
		if (!ok) return;
		await MaterialDetailCtrl.refresh([q_variants, q_material, q_dimensions]);
		if (isNew && f.again) {
			// "Simpan & tambah lagi": modal tetap terbuka, form dikosongkan; R20 bagian 3: Dimension yang baru disimpan tetap terisi
			MaterialDetailCtrl.varForm = { thickness: f.thickness || '' };
			MaterialDetailCtrl.varHint = null;
			MaterialDetailCtrl.varSuggest = null;
			MaterialDetailCtrl.varMsg = { type: 'info', text: `Variant ${f.code} saved. Enter the next variant.` };
			MaterialDetailCtrl.varKey = MaterialDetailCtrl.varKey + 1;
			return;
		}
		closeModal('mdlVarian');
		showAlert(isNew ? `Variant ${f.code} added.` : 'Variant saved.', 'success');
	}

