actionConfiguration.body:
async function () {
		const m = cwVariantForm.model || {};
		if (m.lookupKind === 'suggest') return MaterialDetailCtrl.suggestVariantCode();
		if (m.lookupKind !== 'code') return;      // R20: 'use' hanya di Specsheet
		const code = String(m.lookupCode || '');
		const color = String(m.lookupColor || '');
		const thickness = String(m.lookupThickness || '');
		const seq = MaterialDetailCtrl.varLookupSeq + 1;
		MaterialDetailCtrl.varLookupSeq = seq;
		try {
			const rows = await q_code_hint.run({
				material_id: appsmith.URL.queryParams.id, code, exclude_id: MaterialDetailCtrl.varIsNew ? '' : MaterialDetailCtrl.varForm.id, color, thickness,
			});
			if (seq !== MaterialDetailCtrl.varLookupSeq) return;
			MaterialDetailCtrl.varHint = rows && rows[0] ? Object.assign({ for: `${code}|${color}|${thickness}` }, rows[0]) : null;
		} catch (e) {
			/* hanya bantuan isi otomatis - aturan final tetap di DB */
		}
	}

