async function () {
  const text = String((cwOptionForm.model || ({})).similarQuery || '').trim();
  const seq = OptionCtrl.similarSeq + 1;
  OptionCtrl.similarSeq = seq;
  if (text.length < 2) {
    OptionCtrl.similar = [];
    OptionCtrl.similarFor = text;
    return;
  }
  try {
    const rows = await q_similar.run({
      kind: 'OPTION:' + (OptionCtrl.form.kind || OptionCtrl.kind()),
      text,
      exclude_id: OptionCtrl.form.id || ''
    });
    if (seq !== OptionCtrl.similarSeq) return;
    OptionCtrl.similar = rows || [];
    OptionCtrl.similarFor = text;
  } catch (e) {}
}

