async function () {
  const a = (cwPriceApproval.model || ({})).action || ({});
  const ids = Array.isArray(a.ids) ? a.ids : [];
  if (!ids.length || a.decision !== 'APPROVE' && a.decision !== 'REJECT') return;
  ApprovalCtrl.busy = true;
  ApprovalCtrl.message = null;
  try {
    await a_price_decide.run({
      ids: JSON.stringify(ids),
      decision: a.decision,
      reason: a.reason || ''
    });
    const n = Number(((a_price_decide.data || [])[0] || ({})).n) || ids.length;
    ApprovalCtrl.message = {
      type: 'success',
      text: a.decision === 'APPROVE' ? `${n} price(s) approved. The old price ends on the new price start date.` : `${n} price(s) rejected.`
    };
  } catch (e) {
    const msg = e && e.message;
    if (Util.isSessionError(msg)) {
      await removeValue('token');
      showAlert('Session expired. Please log in again.', 'warning');
      navigateTo('Login');
      return;
    }
    ApprovalCtrl.message = {
      type: 'error',
      text: Util.cleanError(msg)
    };
  } finally {
    ApprovalCtrl.busy = false;
  }
  await ApprovalCtrl.load();
}

