async function (query, params = {}, successMsg = '', refresh = []) {
		try {
			await query.run(params);
		} catch (e) {
			const msg = e && e.message;
			if (Util.isSessionError(msg)) {
				await removeValue('token');
				showAlert('Session expired. Please log in again.', 'warning');
				navigateTo('Login');
				return false;
			}
			showAlert(Util.cleanError(msg), 'error');
			return false;
		}
		if (successMsg) showAlert(successMsg, 'success');
		for (const q of refresh) {
			try { await q.run(); } catch (e) { /* refresh gagal tidak membatalkan aksi */ }
		}
		return true;
	}

