actionConfiguration.body:
async function () {
		// Baca model dulu - model di-reset saat state (Default model) berubah
		const m = cwModelForm.model || {};
		const data = ModelCtrl.modelParams(m);
		if (!data.name || !data.category_id) {
			ModelCtrl.message = { type: 'error', text: 'Model name and category are required.' };
			return;
		}
		ModelCtrl.message = null;
		ModelCtrl.busy = true;
		try {
			await a_model_add.run(data);
		} catch (e) {
			const msg = e && e.message;
			if (Util.isSessionError(msg)) {
				closeModal('mdlModel');
				await removeValue('token');
				showAlert('Session expired. Please log in again.', 'warning');
				navigateTo('Login');
				return;
			}
			ModelCtrl.message = { type: 'error', text: Util.cleanError(msg) };   // mis. nama model sudah ada
			return;
		} finally {
			ModelCtrl.busy = false;
		}
		closeModal('mdlModel');
		const id = a_model_add.data && a_model_add.data[0] && a_model_add.data[0].id;
		showAlert(`Model ${data.name.toUpperCase()} added. Now add its seasons & articles.`, 'success');
		if (id) await Util.goDetail('Model List', 'Model Detail', { id });
	}

