actionConfiguration.body:
async function () {
		const f = cwArticleForm.model || {};
		const isNew = ModelDetailCtrl.articleIsNew;
		const query = isNew ? a_article_add : a_article_update;
		const params = isNew
			? { specsheet_id: ModelDetailCtrl.seasonId, code: f.code, colorway: f.colorway }
			: { id: ModelDetailCtrl.articleForm.id, code: f.code, colorway: f.colorway };
		const ok = await ModelDetailCtrl.runForm(query, params,
			v => { ModelDetailCtrl.articleMsg = v; }, v => { ModelDetailCtrl.articleBusy = v; }, 'mdlArticle');
		if (!ok) return;
		closeModal('mdlArticle');
		showAlert(isNew ? `Article ${f.code || f.colorway} added.` : 'Article saved.', 'success');
		await ModelDetailCtrl.loadArticles();
		await ModelDetailCtrl.refresh([q_seasons]);
	}

