function () {
		const m = ModelDetailCtrl.model();
		if (!m) return '';
		const rows = [
			['Model Name', m.name], ['Factory', m.factory_name], ['Category', m.category], ['Gender', m.gender],
			['Outsole Mould', m.outsole_mold], ['Last No.', m.last_no], ['Construction', m.construction],
			['Size', m.size_range], ['Sample Size', m.sample_size],
		];
		return '<table style="border-collapse:collapse">' + rows.map(([k, v]) =>
			`<tr><td style="padding:4px 24px 4px 0;color:#6b7280">${k}</td><td style="padding:4px 0"><b>${ModelDetailCtrl.esc(v || '-')}</b></td></tr>`
		).join('') + '</table>'
			+ `<div style="margin-top:12px;color:#6b7280;font-size:12px">Changed ${Util.fmtDateTime(m.updated_at)} by ${ModelDetailCtrl.esc(m.updated_by || '-')}</div>`;
	}

