actionConfiguration.body:
function () {
		if (!ModelDetailCtrl.seasonId) {
			return ModelDetailCtrl.seasons().length ? '' : (ModelDetailCtrl.canEdit()
				? 'No seasons yet. Click "+ New Season", then add its articles/colorways here before creating the specsheet.'
				: 'No seasons yet.');
		}
		const n = ModelDetailCtrl.articles().length;
		let t = `${n} article(s) in season ${ModelDetailCtrl.season() ? ModelDetailCtrl.season().season : ''}.`;
		if (ModelDetailCtrl.canEdit() && n) {
			t += ' Articles used in a specsheet/CBD cannot be deleted and their code cannot be changed. Stop using them by dropping them in the specsheet.';
		}
		return t;
	}

