actionConfiguration.body:
async function () {
		const file = fpLampiran.files && fpLampiran.files[0];
		if (!file || !ModelDetailCtrl.article) return;
		if (file.size > ModelDetailCtrl.MAX_BYTES) {
			showAlert(`File size ${ModelDetailCtrl.fmtSize(file.size)}, max 3.5 MB.`, 'error');
			resetWidget('fpLampiran');
			return;
		}
		ModelDetailCtrl.fileBusy = true;
		const ok = await Util.run(a_attachment_add, {
			article_id: ModelDetailCtrl.article.id, file_name: file.name, b64: file.data, note: inpLampiranCatatan.text || '',
		}, `Attachment ${file.name} uploaded.`);
		ModelDetailCtrl.fileBusy = false;
		resetWidget('fpLampiran');
		if (!ok) return;
		resetWidget('inpLampiranCatatan');
		await ModelDetailCtrl.loadAttachments();
		await ModelDetailCtrl.loadArticles();
	}

