FROM article a
LEFT JOIN revision_article ra ON ra.article_id = a.id AND ra.revision_id::text = {{this.params.revision_id || ''}}
WHERE fn_can_see_factory((SELECT fn_auth({{appsmith.store.token}}, 'view_specsheet')), fn_sheet_factory(a.specsheet_id))
  AND a.specsheet_id::text = {{this.params.specsheet_id || ''}}
ORDER BY a.code NULLS LAST, a.colorway;

