      cn.forEach(c => out.push(`<col min="${c}" max="${c}" width="${ws.cols[c].width}" customWidth="1"/>`));
      out.push('</cols>');
    }
    out.push('<sheetData>');
    Object.keys(ws.rows).map(Number).sort((a, b) => a - b).forEach(n => {
      const row = ws.rows[n];
      const cells = Object.keys(row.cells).map(Number).sort((a, b) => a - b).map(c => cellXml(colName(c) + n, row.cells[c], row.font)).join('');
