      u32(central, 0);
      u32(central, offset);
      copy(central, name);
    });
    const cdOffset = out.length;
    copy(out, central);
    u32(out, 0x06054B50);
    u16(out, 0);
    u16(out, 0);
    u16(out, entries.length);
    u16(out, entries.length);
    u32(out, central.length);
    u32(out, cdOffset);
    u16(out, 0);
    return out;
  };
