actionConfiguration.body:
async function (row) {
		const id = row && row.id ? row.id : '';
		SpecCtrl.galleryLogId = id;
		SpecCtrl.galleryImages = [];
		if (!id || !row.image_count) return;
		SpecCtrl.galleryLoading = true;
		let failed = 0;
		try {
			const list = await q_change_log_images.run({ log_id: id });
			for (const i of list || []) {
				if (SpecCtrl.galleryLogId !== id) return;        // baris lain dipilih
				try {
					const rows = await q_change_log_image.run({ id: i.id });
					const d = rows && rows[0];
					if (d && SpecCtrl.galleryLogId === id) {
						SpecCtrl.galleryImages = SpecCtrl.galleryImages.concat([
							{ id: i.id, name: i.file_name, mime: i.mime_type, size: i.size_bytes, data: d.data }]);
					}
				} catch (e) {
					failed += 1;
				}
			}
			if (failed) showAlert(`${failed} image(s) could not be loaded.`, 'warning');
		} catch (e) {
			showAlert(Util.cleanError(e && e.message), 'error');
		} finally {
			if (SpecCtrl.galleryLogId === id) SpecCtrl.galleryLoading = false;
		}
	}

