actionConfiguration.body:
async function () {
		const f = cwPublishForm.model || {};
		const images = Array.isArray(f.images) ? f.images : [];
		const r = SpecCtrl.revision();
		if (!r) return;
		SpecCtrl.pubMsg = null;
		SpecCtrl.pubBusy = true;
		try {
			await a_revision_publish.run({ revision_id: r.id, category: f.category || '', reason: f.reason || '' });
		} catch (e) {
			const msg = e && e.message;
			if (Util.isSessionError(msg)) {
				closeModal('mdlTerbit');
				await removeValue('token');
				showAlert('Session expired. Please log in again.', 'warning');
				navigateTo('Login');
				return;
			}
			SpecCtrl.pubMsg = { type: 'error', text: Util.cleanError(msg) };
			return;
		} finally {
			SpecCtrl.pubBusy = false;
		}
		const logId = ((a_revision_publish.data || [])[0] || {}).id;
		const failed = await SpecCtrl.attachImages(logId, images);
		closeModal('mdlTerbit');
		showAlert(`Revision ${SpecCtrl.label(r)} published.`
			+ (failed ? ` ${failed} image(s) could not be attached.` : (images.length ? ` ${images.length} image(s) attached.` : '')),
			failed ? 'warning' : 'success');
		await SpecCtrl.nav({ type: 'reload', seasons: true, pick: r.id });
	}

