async function () {
		const m = SpecCtrl.model();
		const s = SpecCtrl.season();
		const r = SpecCtrl.revision();
		if (!m || !s || !r) return showAlert('Open a specsheet revision first.', 'warning');
		SpecExportCtrl.busy = true;
		SpecExportCtrl.step = 'building the content';
		try {
			const wb = SpecExportCtrl.build(m, s, r);
			await SpecExportCtrl.save(wb, SpecExportCtrl.fileName('Specsheet', m.name, s.season, `${Util.stageLabel(r.stage)}-r${r.revision_no}`, r.status === 'DRAFT' ? 'DRAFT' : ''));
			showAlert('Specsheet Excel file downloaded.', 'success');
		} catch (e) {
			showAlert(`Export failed while ${SpecExportCtrl.step}: ` + Util.cleanError((e && e.message) || String(e)), 'error');
		} finally {
			SpecExportCtrl.busy = false;
		}
	}

