async function (req) {
		const prev = SpecCtrl.navNext;
		SpecCtrl.navNext = prev && prev.type === 'reload' && req.type === 'revision'
			? Object.assign({}, prev, { pick: req.id }) : req;
		if (SpecCtrl.navBusy) return;
		SpecCtrl.navBusy = true;
		try {
			while (SpecCtrl.navNext) {
				const r = SpecCtrl.navNext;
				SpecCtrl.navNext = null;
				try {
					await SpecCtrl.runNav(r);
				} catch (e) {
					showAlert(Util.cleanError(e && e.message), 'error');
				}
			}
		} finally {
			SpecCtrl.navBusy = false;
		}
	}

