async function (r) {
		if (r.type === 'init') return SpecCtrl.loadInit();
		if (r.type === 'model') {
			SpecCtrl.modelId = r.id || '';
			return SpecCtrl.loadModel('');
		}
		if (r.type === 'season') {
			SpecCtrl.seasonId = r.id || '';
			SpecCtrl.revisionId = '';
			return SpecCtrl.loadSeason();
		}
		if (r.type === 'revision') {
			if (!r.id || r.id === SpecCtrl.revisionId) return;
			SpecCtrl.revisionId = r.id;
			return BomCtrl.load();
		}
		if (r.type === 'reload') {
			if (r.seasons) await SpecCtrl.refreshSeasons();
			if (r.clear) SpecCtrl.revisionId = '';
			return SpecCtrl.loadSeason(r.pick);
		}
	}

