async function () {
		const f = cwVariantForm.model || {};
		const c = BomCtrl.varCtx || {};
		const code = String(f.code || '').trim();
		if (!code) {
			BomCtrl.varMsg = { type: 'error', text: 'Material Code is required.' };
			return;
		}
		BomCtrl.varMsg = null;
		BomCtrl.varBusy = true;
		try {
			await a_variant_save.run({
				id: '', material_id: c.material_id, code, color: c.color, thickness: c.thickness, status: 'ACTIVE',
			});
		} catch (e) {
			const msg = e && e.message;
			if (Util.isSessionError(msg)) {
				closeModal('mdlVarianBaru');
				await removeValue('token');
				showAlert('Session expired. Please log in again.', 'warning');
				navigateTo('Login');
				return;
			}
			BomCtrl.varMsg = { type: 'error', text: Util.cleanError(msg) };
			return;
		} finally {
			BomCtrl.varBusy = false;
		}
		closeModal('mdlVarianBaru');
		showAlert(`Variant ${code.toUpperCase()} registered. Cell ${c.color} linked automatically.`, 'success');
		await BomCtrl.reload(['options']);
	}

