async function () {
		const m = cwVariantForm.model || {};
		if (m.lookupKind === 'suggest') return BomCtrl.suggestVariantCode();
		if (m.lookupKind === 'use') return BomCtrl.useFromRegister(m.useId, m.useCode);
		const code = String(m.lookupCode || '');
		const color = String(m.lookupColor || '');
		const thickness = String(m.lookupThickness || '');
		const c = BomCtrl.varCtx || {};
		const seq = BomCtrl.varLookupSeq + 1;
		BomCtrl.varLookupSeq = seq;
		try {
			const rows = await q_code_hint.run({ material_id: c.material_id, code, exclude_id: '', color, thickness });
			if (seq !== BomCtrl.varLookupSeq) return;
			BomCtrl.varHint = rows && rows[0] ? Object.assign({ for: `${code}|${color}|${thickness}` }, rows[0]) : null;
		} catch (e) {
			/* hanya bantuan - aturan final di DB */
		}
	}

