actionConfiguration.body:
async function () {
		const name = String((cwSupplierForm.model || {}).name || '').trim();
		if (!name) {
			BomCtrl.supMsg = { type: 'error', text: 'Supplier name is required.' };
			return;
		}
		BomCtrl.supMsg = null;
		BomCtrl.supBusy = true;
		try {
			await a_supplier_insert.run({ name });
		} catch (e) {
			const msg = e && e.message;
			if (Util.isSessionError(msg)) {
				closeModal('mdlSupplierBaru');
				await removeValue('token');
				showAlert('Session expired. Please log in again.', 'warning');
				navigateTo('Login');
				return;
			}
			BomCtrl.supMsg = { type: 'error', text: Util.cleanError(msg) };
			return;
		} finally {
			BomCtrl.supBusy = false;
		}
		closeModal('mdlSupplierBaru');
		showAlert(`Supplier ${name.toUpperCase()} added. Type its name in the Supplier column.`, 'success');
		await BomCtrl.reload(['options']);
	}

