SELECT s.id, s.season, s.season_sort, fn_rev_label(sp.stage, sp.revision_no) AS spec_pub_label
FROM specsheet s
LEFT JOIN specsheet_revision sp ON sp.id = fn_spec_latest_pub(s.id)
WHERE fn_can_see_factory((SELECT fn_auth({{appsmith.store.token}}, 'view_cbd')), fn_model_factory(s.model_id))
  AND s.model_id::text = {{this.params.model_id || ''}}
ORDER BY s.season_sort DESC;

SELECT s.id, s.season, s.season_sort, fn_rev_label(sp.stage, sp.revision_no) AS spec_pub_label
FROM specsheet s
LEFT JOIN specsheet_revision sp ON sp.id = fn_spec_latest_pub(s.id)
WHERE fn_can_see_factory((SELECT fn_auth({{appsmith.store.token}}, 'view_cbd')), fn_model_factory(s.model_id))
  AND s.model_id::text = {{this.params.model_id || ''}}
ORDER BY s.season_sort DESC;

