function () {
  const MAIN = 'http://schemas.openxmlformats.org/spreadsheetml/2006/main';
  const REL = 'http://schemas.openxmlformats.org/officeDocument/2006/relationships';
  const PKG = 'http://schemas.openxmlformats.org/package/2006/relationships';
  const HEAD = '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>\n';
  const esc = s => String(s).replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F]/g, '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
  const colName = c => {
    let s = '';
    while (c > 0) {
      const m = (c - 1) % 26;
      s = String.fromCharCode(65 + m) + s;
      c = Math.floor((c - 1) / 26);
    }
    return s;
  };
  const parseRef = ref => {
    const m = (/^([A-Z]+)(\d+)$/).exec(String(ref).trim().toUpperCase());
    if (!m) throw new Error('Invalid cell address: ' + ref);
    let c = 0;
    for (let i = 0; i < m[1].length; i++) c = c * 26 + m[1].charCodeAt(i) - 64;
    return [Number(m[2]), c];
  };
  const isDate = v => Object.prototype.toString.call(v) === '[object Date]' && !isNaN(v.getTime());
  const serial = d => (d.getTime() - d.getTimezoneOffset() * 60000) / 86400000 + 25569;
  const sheets = [];
  const makeSheet = (name, opts) => {
    const rows = {};
    const cols = {};
    const merges = [];
    let last = 0;
    const getRow = n => {
      if (!rows[n]) {
        const cells = {};
        rows[n] = {
          number: n,
          height: null,
          font: null,
          cells,
          getCell(c) {
            if (!cells[c]) cells[c] = {
              value: null
            };
            return cells[c];
          }
        };
        if (n > last) last = n;
      }
      return rows[n];
    };
    return {
      name,
      pageSetup: opts.pageSetup || null,
      views: [],
      rows,
      cols,
      merges,
      printTitleRows: null,
      footer: null,
      getRow,
      getColumn(c) {
        if (!cols[c]) cols[c] = {
          width: null
        };
        return cols[c];
      },
      getCell(ref) {
        const rc = parseRef(ref);
        return getRow(rc[0]).getCell(rc[1]);
      },
      addRow(values) {
        const row = getRow(last + 1);
        (values || []).forEach((v, i) => {
          row.getCell(i + 1).value = v;
        });
