      const m = (c - 1) % 26;
      s = String.fromCharCode(65 + m) + s;
      c = Math.floor((c - 1) / 26);
    }
    return s;
  };
  const parseRef = ref => {
    const m = (/^([A-Z]+)(\d+)$/).exec(String(ref).trim().toUpperCase());
    if (!m) throw new Error('Invalid cell address: ' + ref);
    let c = 0;
    for (let i = 0; i < m[1].length; i++) c = c * 26 + m[1].charCodeAt(i) - 64;
    return [Number(m[2]), c];
  };
