  const sheets = [];
  const makeSheet = (name, opts) => {
    const rows = {};
    const cols = {};
    const merges = [];
    let last = 0;
    const getRow = n => {
      if (!rows[n]) {
        const cells = {};
        rows[n] = {
          number: n,
          height: null,
          font: null,
          cells,
          getCell(c) {
            if (!cells[c]) cells[c] = {
              value: null
            };
            return cells[c];
          }
        };
        if (n > last) last = n;
      }
      return rows[n];
    };
    return {
      name,
      pageSetup: opts.pageSetup || null,
      views: [],
      rows,
      cols,
      merges,
      printTitleRows: null,
      footer: null,
      getRow,
      getColumn(c) {
        if (!cols[c]) cols[c] = {
          width: null
        };
        return cols[c];
      },
      getCell(ref) {
        const rc = parseRef(ref);
        return getRow(rc[0]).getCell(rc[1]);
      },
      addRow(values) {
        const row = getRow(last + 1);
        (values || []).forEach((v, i) => {
          row.getCell(i + 1).value = v;
        });
        return row;
      },
      mergeCells(a, b, c, d) {
        if (typeof a === 'string') {
          const p = a.split(':');
          const s = parseRef(p[0]);
          const e = parseRef(p[1]);
          merges.push([s[0], s[1], e[0], e[1]]);
