      u16(out, 0x0800);
      u16(out, 0);
      u16(out, time);
      u16(out, date);
      u32(out, crc);
      u32(out, data.length);
      u32(out, data.length);
      u16(out, name.length);
      u16(out, 0);
      copy(out, name);
      copy(out, data);
      u32(central, 0x02014B50);
      u16(central, 20);
      u16(central, 20);
      u16(central, 0x0800);
      u16(central, 0);
      u16(central, time);
      u16(central, date);
      u32(central, crc);
      u32(central, data.length);
      u32(central, data.length);
      u16(central, name.length);
      u16(central, 0);
      u16(central, 0);
      u16(central, 0);
      u16(central, 0);
      u32(central, 0);
      u32(central, offset);
      copy(central, name);
    });
    const cdOffset = out.length;
    copy(out, central);
    u32(out, 0x06054B50);
    u16(out, 0);
    u16(out, 0);
    u16(out, entries.length);
    u16(out, entries.length);
    u32(out, central.length);
    u32(out, cdOffset);
    u16(out, 0);
    return out;
  };
  const base64 = bytes => {
    const t = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';
    const out = [];
    for (let i = 0; i < bytes.length; i += 3) {
      const x = bytes[i] << 16 | (bytes[i + 1] || 0) << 8 | (bytes[i + 2] || 0);
      out.push(t[x >> 18 & 63] + t[x >> 12 & 63] + (i + 1 < bytes.length ? t[x >> 6 & 63] : '=') + (i + 2 < bytes.length ? t[x & 63] : '='));
    }
    return out.join('');
  };
  const wb = {
    creator: '',
    created: new Date(),
    addWorksheet(name, opts) {
      const ws = makeSheet(name, opts || ({}));
      sheets.push(ws);
      return ws;
    },
    toBase64() {
      return base64(zip(files(wb), isDate(wb.created) ? wb.created : new Date()));
    }
  };
  return wb;
}

