actionConfiguration.body:
async function () {
		const m = CbdCtrl.model();
		const s = CbdCtrl.season();
		const a = CbdCtrl.article();
		const r = CbdCtrl.revision();
		if (!m || !s || !a || !r) return showAlert('Open a CBD revision first.', 'warning');
		CbdExportCtrl.busy = true;
		CbdExportCtrl.step = 'loading the change breakdown';
		try {
			let withBridge = true;           // gagal dimuat -> export tetap jalan tanpa blok rincian
			try {
				await q_cbd_bridge.run({ revision_id: r.id });
			} catch (e) {
				withBridge = false;
			}
			CbdExportCtrl.step = 'building the content';
			const wb = CbdExportCtrl.build(m, s, a, r, withBridge);
			await CbdExportCtrl.save(wb, CbdExportCtrl.fileName('CBD', m.name, s.season, CbdCtrl.artLabel(a), `${Util.stageLabel(r.stage)}-r${r.revision_no}`, r.status === 'DRAFT' ? 'DRAFT' : ''));
			showAlert('CBD Excel file downloaded.', 'success');
		} catch (e) {
			showAlert(`Export failed while ${CbdExportCtrl.step}: ` + Util.cleanError((e && e.message) || String(e)), 'error');
		} finally {
			CbdExportCtrl.busy = false;
		}
	}

