actionConfiguration.body:
function (m, s, a, r, withBridge) {
		const N = 15;
		const lines = CbdGridCtrl.lines();
		const rc = CbdGridCtrl.recap() || {};
		const items = CbdGridCtrl.costItems();
		const log = r.status === 'PUBLISHED' ? CbdCtrl.logFor(r.id) : null;
		const rate = CbdExportCtrl.n(r.exchange_rate);

		const wb = XlsxWriter.workbook();
		wb.creator = (Auth.me && Auth.me.full_name) || '';
		wb.created = new Date();
		const ws = wb.addWorksheet(`${CbdCtrl.artLabel(a)} ${Util.revLabel(r)}`.slice(0, 31), {   // R19: tanpa nomor = colorway
			pageSetup: { orientation: 'landscape', paperSize: 9, fitToPage: true, fitToWidth: 1, fitToHeight: 0 },
		});
		[6, 24, 34, 11, 9, 18, 10, 10, 8, 13, 15, 17, 18, 20, 16].forEach((w, i) => { ws.getColumn(i + 1).width = w; });

		// ---- header (baris 1–8) ----
		ws.getCell('A1').value = 'Cost Breakdown Sheet';
		ws.getCell('A1').font = { bold: true, size: 16, color: { argb: CbdExportCtrl.NAVY } };
		ws.getCell('A2').value = 'Confidential Information';
		ws.getCell('A2').font = { italic: true, color: { argb: 'FF6B7280' } };
		ws.getCell('K2').value = 'Date';
		// R12 (T67): tanggal WIB (sel Excel memakai tanggal lokal PC)
		ws.getCell('L2').value = new Date(moment(r.status === 'PUBLISHED' && r.published_at ? r.published_at : undefined)
			.utcOffset(7).format('YYYY-MM-DD') + 'T00:00:00');
		ws.getCell('L2').numFmt = 'dd-mmm-yyyy';
		ws.getCell('K3').value = '1 $ =';
		ws.getCell('K3').alignment = { horizontal: 'right' };
		ws.getCell('L3').value = rate;
		ws.getCell('L3').numFmt = CbdExportCtrl.RP;
		ws.getCell('L3').font = { bold: true, size: 14 };
		const v = x => x || '-';
		const info = [
			['Model Name', `${m.name} (${v(m.factory_name)}); Mold: ${v(m.outsole_mold)}; Last: ${v(m.last_no)}; Size Range: ${v(m.size_range)}`],
			['Article #', `${a.code}`],
			['Construction', v(m.construction)],
			['Color', v(a.colorway)],
			['Season / Revision', `${s.season} · ${Util.revLabel(r)} · ${r.status}`
				+ (r.status === 'PUBLISHED' ? ` · published by ${r.published_by || '-'}` : ' · NOT PUBLISHED')
				+ ` · reference specsheet ${r.spec_label || '-'}`],
		];
		info.forEach(([k, val], i) => {
			ws.getCell(`B${4 + i}`).value = k;
			ws.getCell(`B${4 + i}`).font = { bold: true };
			ws.getCell(`C${4 + i}`).value = val;
		});
		ws.getCell('C8').font = { bold: true, color: { argb: r.status === 'PUBLISHED' ? 'FF16A34A' : 'FFDC2626' } };

		// ---- header tabel (baris 10–11) ----
		const h1 = ws.getRow(10);
		const h2 = ws.getRow(11);
		['No', 'Component Name', 'Material description', 'Dimension', 'Unit', 'Color', 'Yield', 'Usage', 'Loss %',
			'Unit Price', '', 'Cost/pr (Rp)', 'Supplier', 'Remarks', 'Source'].forEach((t, i) => { h1.getCell(i + 1).value = t; });
		h2.getCell(10).value = 'USD';
		h2.getCell(11).value = 'IDR';
		ws.mergeCells('J10:K10');
		[1, 2, 3, 4, 5, 6, 7, 8, 9, 12, 13, 14, 15].forEach(c => ws.mergeCells(10, c, 11, c));
		[h1, h2].forEach(row => {
			CbdExportCtrl.fill(row, 1, N, CbdExportCtrl.NAVY);
			CbdExportCtrl.box(row, 1, N);
			for (let c = 1; c <= N; c++) {
				row.getCell(c).font = { bold: true, color: { argb: 'FFFFFFFF' } };
				row.getCell(c).alignment = { horizontal: 'center', vertical: 'middle', wrapText: true };
			}
		});

		// ---- baris material ----
		const writeLine = (l, counted) => {
			const row = ws.addRow([]);
			const i = row.number;
			const y = CbdExportCtrl.n(l.yield_value);
			const p = CbdExportCtrl.n(l.price_original);
			row.getCell(1).value = l.is_sub ? '' : (l.display_no || '');
			row.getCell(2).value = (l.is_sub ? '↳ ' : '') + (l.display_name || '') + (l.is_local ? ' (local)' : '');
			row.getCell(3).value = `${l.material_name || ''}${l.material_code ? ' [' + l.material_code + ']'
				: l.price_method === 'CATALOG' ? ' (no code)' : ''}`;
			row.getCell(4).value = l.thickness || '';
			row.getCell(5).value = l.uom || '';
			row.getCell(6).value = l.color || '';
			row.getCell(7).value = y;
			row.getCell(8).value = y ? CbdExportCtrl.f(`1/G${i}`, CbdExportCtrl.n(l.usage_value)) : null;
			row.getCell(9).value = CbdExportCtrl.n(l.loss_pct) ?? 0;
			if (p !== null && l.currency === 'USD') {
				row.getCell(10).value = p;
				row.getCell(11).value = CbdExportCtrl.f(`J${i}*$L$3`, CbdExportCtrl.n(l.price_idr));
			} else if (p !== null) {
				row.getCell(11).value = p;
			}
			if (counted && l.no_charge) {
				row.getCell(12).value = 0;          // R11: tanpa biaya - harga termasuk baris lain
			} else if (counted && y && p !== null && (l.currency === 'IDR' || rate)) {
				row.getCell(12).value = CbdExportCtrl.f(`H${i}*(1+I${i}/100)*K${i}`, CbdExportCtrl.n(l.cost_per_pair));
			}
			row.getCell(13).value = l.supplier_name || '';
			row.getCell(14).value = l.remarks || '';
			const src = { MASTER: 'master price', OVERRIDE: 'override', QUOTATION: 'quotation', ESTIMATE: 'estimate' }[l.price_source] || 'no price';
			const org = { INPUT: '', COPIED: ' · copy', CARRIED_FROM_REPLACED: ' · replaced material' }[l.value_origin] || '';
			row.getCell(15).value = l.no_charge ? `no charge: ${l.no_charge_reason || '-'}`
				: src + org + (l.price_source === 'OVERRIDE' && l.price_override_reason ? `: ${l.price_override_reason}` : '');
			row.getCell(7).numFmt = '#,##0.00####';
			row.getCell(8).numFmt = '0.000000';
			row.getCell(9).numFmt = '0.00';
			row.getCell(10).numFmt = CbdExportCtrl.USD;
			row.getCell(11).numFmt = CbdExportCtrl.RP;
			row.getCell(12).numFmt = CbdExportCtrl.RP;
			CbdExportCtrl.box(row, 1, N);
			for (let c = 1; c <= N; c++) row.getCell(c).alignment = { vertical: 'top', wrapText: c <= 6 || c >= 13 };
			if (!counted) for (let c = 1; c <= N; c++) row.getCell(c).font = { color: { argb: 'FF9CA3AF' } };
			// R17: baris tanpa Material Code (Pullover / Preview) kuning, sama dengan sel kuning di Excel specsheet
			if (counted && !l.material_code && l.price_method === 'CATALOG') CbdExportCtrl.fill(row, 1, N, CbdExportCtrl.YELLOW);
			return i;
		};

		const groupHeader = (label, argb) => {
			const row = ws.addRow([label]);
			ws.mergeCells(row.number, 1, row.number, N);
			row.getCell(1).font = { bold: true, color: { argb: CbdExportCtrl.NAVY } };
			CbdExportCtrl.fill(row, 1, N, argb);
		};

		const active = lines.filter(l => l.status === 'ACTIVE');
		const missing = lines.filter(l => l.status !== 'ACTIVE');
		const groups = [];
		active.forEach(l => {
			let g = groups[groups.length - 1];
			if (!g || g.code !== l.group_code) groups.push(g = { code: l.group_code, name: l.group_name, lines: [] });
			g.lines.push(l);
		});
		const subtotalCells = [];
		const gc = rc.group_costs || {};
		groups.forEach(g => {
			groupHeader(`${String(g.code || '').toLowerCase()}. ${g.name || ''}`, CbdExportCtrl.GROUP_FILL);
			const rows = g.lines.map(l => writeLine(l, true));
			const st = ws.addRow([]);
			st.getCell(2).value = `Subtotal ${String(g.code || '').toUpperCase()} · ${g.name || ''}`;
			st.getCell(12).value = CbdExportCtrl.f(`SUM(L${rows[0]}:L${rows[rows.length - 1]})`, CbdExportCtrl.n(gc[g.code]) ?? 0);
			st.getCell(12).numFmt = CbdExportCtrl.RP;
			st.font = { bold: true };
			CbdExportCtrl.box(st, 1, N);
			subtotalCells.push(`L${st.number}`);
			ws.addRow([]);
		});
		if (!groups.length) ws.addRow(['No CBD lines yet.']);
		if (missing.length) {
			groupHeader(`Missing from specsheet (MISSING_IN_SPEC): ${missing.length} lines, not counted`, CbdExportCtrl.MISSING_FILL);
			missing.forEach(l => writeLine(l, false));
			ws.addRow([]);
		}

		// ---- Cost recapitulation (kolom G–L, keterangan di M) ----
		ws.addRow([]);
		const title = ws.addRow([]);
		title.getCell(7).value = 'Cost recapitulation';
		title.getCell(7).font = { bold: true, size: 12, color: { argb: CbdExportCtrl.NAVY } };
		const recapRow = (label, value, note, bold) => {
			const row = ws.addRow([]);
			row.getCell(7).value = label;
			row.getCell(12).value = value;
			row.getCell(12).numFmt = CbdExportCtrl.RP;
			if (note) row.getCell(13).value = note;
			if (bold) row.font = { bold: true };
			ws.mergeCells(row.number, 7, row.number, 11);
			CbdExportCtrl.box(row, 7, 13);
			return row.number;
		};
		const letter = i => String.fromCharCode(97 + i) + '.';
		const first = recapRow(`${letter(0)} Material Cost`,
			CbdExportCtrl.f(subtotalCells.length ? `SUM(${subtotalCells.join(',')})` : '0', CbdExportCtrl.n(rc.material_cost) ?? 0), '', true);
		let last = first;
		items.forEach((it, i) => {
			last = recapRow(`${letter(i + 1)} ${it.name || CbdExportCtrl.COST_LABEL[it.item_type]}`, CbdExportCtrl.n(it.amount) ?? 0, it.remarks || '');
		});
		const fobRow = recapRow('ACTUAL FOB', CbdExportCtrl.f(`SUM(L${first}:L${last})`, CbdExportCtrl.n(rc.actual_fob)), 'material cost + all costs', true);
		ws.getRow(fobRow).getCell(12).fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: CbdExportCtrl.GROUP_FILL } };

		ws.addRow([]);
		const tRow = ws.addRow([]);
		tRow.getCell(11).value = 'TARGET FOB';
		tRow.getCell(12).value = CbdExportCtrl.n(rc.target_fob);
		tRow.getCell(12).numFmt = CbdExportCtrl.RP;
		const t = tRow.number;
		const vRow = ws.addRow([]);
		if (tRow.getCell(12).value !== null) {
			vRow.getCell(11).value = CbdExportCtrl.f(`IF(L${fobRow}>L${t},"OVER",IF(L${fobRow}<L${t},"UNDER","MATCH"))`, rc.variance_label || null);
			vRow.getCell(12).value = CbdExportCtrl.f(`L${fobRow}-L${t}`, CbdExportCtrl.n(rc.variance));
			vRow.getCell(12).numFmt = CbdExportCtrl.RP;
			vRow.getCell(11).font = { bold: true, color: { argb: rc.variance_label === 'OVER' ? 'FFDC2626' : 'FF16A34A' } };
		}
		[tRow, vRow].forEach(row => { row.getCell(11).alignment = { horizontal: 'right' }; });

		// ---- R5: PO (mis. SMS = Actual FOB x 1,25). Selling price & margin tidak ada di CBD. ----
		const factor = CbdExportCtrl.n(rc.po_factor);
		if (factor) {
			const pRow = recapRow(`PO ${Util.stageLabel(r.stage)} (Actual FOB × ${String(factor).replace('.', ',')})`,
				CbdExportCtrl.f(`ROUND(L${fobRow}*${factor},2)`, CbdExportCtrl.n(rc.po_price)), 'PO price to brand', true);
			ws.getRow(pRow).getCell(12).fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: CbdExportCtrl.GROUP_FILL } };
		}

		// ---- change log revisi ini ----
		if (log) {
			ws.addRow([]);
			const c = ws.addRow(['', 'Change log']);
			c.getCell(2).font = { bold: true };
			const ch = ws.addRow(['', 'Date', 'Category', 'By', '', 'Reason']);
			ch.font = { bold: true };
			ws.addRow(['', moment(log.created_at).utcOffset(7).format('DD-MM-YYYY HH:mm'), log.category, log.created_by, '', log.reason]);
		}

		// ---- R11 (A4): rincian perubahan vs revisi terbit sebelumnya ----
		const bridge = withBridge ? CbdCtrl.bridgeRows() : [];
		if (bridge.length) {
			ws.addRow([]);
			const bt = ws.addRow(['', `Change breakdown vs ${bridge[0].prev_label || 'previous revision'}`]);
			bt.getCell(2).font = { bold: true, color: { argb: CbdExportCtrl.NAVY } };
			const bh = ws.addRow(['', 'Category', 'Description']);
			bh.getCell(12).value = 'Value (Rp)';
			ws.mergeCells(bh.number, 3, bh.number, 11);
			CbdExportCtrl.fill(bh, 2, 12, CbdExportCtrl.GROUP_FILL);
			CbdExportCtrl.box(bh, 2, 12);
			bh.font = { bold: true };
			const firstB = bh.number + 1;
			bridge.forEach(x => {
				const row = ws.addRow(['', x.category_label || x.category, x.description || '']);
				row.getCell(12).value = CbdExportCtrl.n(x.amount);
				row.getCell(12).numFmt = CbdExportCtrl.RP;
				ws.mergeCells(row.number, 3, row.number, 11);
				row.getCell(3).alignment = { wrapText: true, vertical: 'top' };
				CbdExportCtrl.box(row, 2, 12);
			});
			const lastB = firstB + bridge.length - 1;
			const tot = ws.addRow(['', 'Actual FOB difference',
				`${bridge[0].prev_label || ''}: ${Util.fmtNum(bridge[0].prev_fob, 2)} → ${Util.revLabel(r)}: ${Util.fmtNum(bridge[0].fob, 2)}`]);
			const delta = CbdExportCtrl.n(bridge[0].fob) !== null && CbdExportCtrl.n(bridge[0].prev_fob) !== null
				? CbdExportCtrl.n(bridge[0].fob) - CbdExportCtrl.n(bridge[0].prev_fob) : null;
			tot.getCell(12).value = CbdExportCtrl.f(`SUM(L${firstB}:L${lastB})`, delta);
			tot.getCell(12).numFmt = CbdExportCtrl.RP;
			ws.mergeCells(tot.number, 3, tot.number, 11);
			CbdExportCtrl.box(tot, 2, 12);
			tot.font = { bold: true };
		}

		ws.views = [{ state: 'frozen', xSplit: 3, ySplit: 11 }];
		return wb;
	}

