actionConfiguration.body:
async function (row) {
		const id = row && row.id ? row.id : '';
		CbdCtrl.galleryLogId = id;
		CbdCtrl.galleryImages = [];
		if (!id || !row.image_count) return;
		CbdCtrl.galleryLoading = true;
		let failed = 0;
		try {
			const list = await q_change_log_images.run({ log_id: id });
			for (const i of list || []) {
				if (CbdCtrl.galleryLogId !== id) return;        // baris lain dipilih
				try {
					const rows = await q_change_log_image.run({ id: i.id });
					const d = rows && rows[0];
					if (d && CbdCtrl.galleryLogId === id) {
						CbdCtrl.galleryImages = CbdCtrl.galleryImages.concat([
							{ id: i.id, name: i.file_name, mime: i.mime_type, size: i.size_bytes, data: d.data }]);
					}
				} catch (e) {
					failed += 1;
				}
			}
			if (failed) showAlert(`${failed} image(s) could not be loaded.`, 'warning');
		} catch (e) {
			showAlert(Util.cleanError(e && e.message), 'error');
		} finally {
			if (CbdCtrl.galleryLogId === id) CbdCtrl.galleryLoading = false;
		}
	}

