actionConfiguration.body:
async function (showError) {
		try {
			for (let i = 0; i < 3; i++) {
				const g = CbdGridCtrl.loadGen + 1;
				CbdGridCtrl.loadGen = g;
				const p = { revision_id: CbdGridCtrl.revId() };
				await Promise.all([q_cbd_lines.run(p), q_cbd_recap.run(p), q_cbd_cost_items.run(p)]);
				const stale = g < CbdGridCtrl.doneGen || CbdGridCtrl.revId() !== p.revision_id;
				CbdGridCtrl.doneGen = Math.max(CbdGridCtrl.doneGen, g);
				if (!stale) return;
			}
		} catch (e) {
			if (showError) showAlert(Util.cleanError(e && e.message), 'error');
		}
	}

