actionConfiguration.body:
async function (pickId) {
		try {
			await Promise.all([
				q_cbd_revisions.run({ article_id: CbdCtrl.articleId || '' }),
				q_cbd_change_log.run({ article_id: CbdCtrl.articleId || '' }),
			]);
		} catch (e) {
			showAlert(Util.cleanError(e && e.message), 'error');
		}
		const revs = CbdCtrl.revisions();
		const keep = revs.find(r => r.id === (pickId || CbdCtrl.revisionId));
		const pick = keep || CbdCtrl.draft() || CbdCtrl.latestPublished() || revs[revs.length - 1] || null;
		CbdCtrl.revisionId = pick ? pick.id : '';
		await CbdGridCtrl.load();
	}

