actionConfiguration.body:
async function (a) {
		const r = CbdCtrl.revision();
		if (!r) return;
		switch (a.type) {
			case 'setYield':
			case 'setLoss':
				await CbdGridCtrl.exec(a_cbd_line_set, { line_id: a.line_id, field: a.type === 'setYield' ? 'YIELD' : 'LOSS', value: a.value ?? '' });
				break;
			case 'setHeader':
				await CbdGridCtrl.exec(a_cbd_header_set, { revision_id: r.id, field: a.field, value: a.value ?? '' });
				break;
			case 'addCost':
				if (await CbdGridCtrl.exec(a_cbd_cost_add, {
					revision_id: r.id, item_type: a.item_type, name: a.name || '', amount: a.amount ?? '', remarks: a.remarks || '',
				})) CbdGridCtrl.costOkKey = CbdGridCtrl.costOkKey + 1;
				break;
			case 'setCost':
				await CbdGridCtrl.exec(a_cbd_cost_set, { item_id: a.item_id, field: a.field, value: a.value ?? '' });
				break;
			case 'deleteCost':      // a_cbd_cost_delete: Request confirmation = ON
				await CbdGridCtrl.exec(a_cbd_cost_delete, { item_id: a.item_id });
				break;
			case 'editPrice':       // mode QUOTATION / ESTIMATE (R17)
				await CbdGridCtrl.openPrice(a.line_id, a.mode);
				break;
			case 'proposePrice':    // R8: harga master untuk varian × supplier baris ini
				await CbdGridCtrl.openPrice(a.line_id, 'PROPOSE');
				break;
			case 'setNoCharge':     // R11: tanpa biaya (alasan wajib) / batalkan
				if (await CbdGridCtrl.exec(a_cbd_no_charge, { line_id: a.line_id, on: a.on ? 'true' : 'false', reason: a.reason || '' })) {
					showAlert(a.on ? 'Line marked as no charge (cost 0).' : 'No-charge mark removed.', 'success');
				}
				break;
			case 'refreshPrices':
				if (await CbdGridCtrl.exec(a_cbd_refresh_prices, { revision_id: r.id })) {
					const n = a_cbd_refresh_prices.data && a_cbd_refresh_prices.data[0] && a_cbd_refresh_prices.data[0].n;
					showAlert(`Prices of ${n || ''} line(s) updated from master.`, 'success');
				}
				break;
			case 'refreshSpec':     // a_cbd_refresh_spec: Request confirmation = ON
				if (await CbdGridCtrl.exec(a_cbd_refresh_spec, { revision_id: r.id })) {
					showAlert(`CBD refreshed from the latest published ${Util.stageLabel(r.stage)} specsheet.`, 'success');
					await CbdCtrl.refresh(r.id);   // acuan & baris berubah (R13: stage tetap)
				}
				break;
		}
	}

