async function (req) {
		const prev = CbdCtrl.navNext;
		let next = req;
		if (prev && prev.type === 'reload' && req.type === 'revision') next = Object.assign({}, prev, { pick: req.id });
		if (prev && prev.type === 'reload' && req.type === 'article') next = Object.assign({}, prev, { article: req.id, pick: '' });
		CbdCtrl.navNext = next;
		if (CbdCtrl.navBusy) return;
		CbdCtrl.navBusy = true;
		try {
			while (CbdCtrl.navNext) {
				const r = CbdCtrl.navNext;
				CbdCtrl.navNext = null;
