async function (r) {
		if (r.type === 'init') return CbdCtrl.loadInit();
		if (r.type === 'model') {
			CbdCtrl.modelId = r.id || '';
			return CbdCtrl.loadModel('');
		}
		if (r.type === 'season') {
			CbdCtrl.seasonId = r.id || '';
			CbdCtrl.articleId = '';
			CbdCtrl.revisionId = '';
			return CbdCtrl.loadSeason();
		}
		if (r.type === 'article') {
			if (!r.id || r.id === CbdCtrl.articleId) return;
			CbdCtrl.articleId = r.id;
			CbdCtrl.revisionId = '';
			return CbdCtrl.loadArticle();
		}
		if (r.type === 'revision') {
			if (!r.id || r.id === CbdCtrl.revisionId) return;
			CbdCtrl.revisionId = r.id;
			return CbdGridCtrl.load();
		}
		if (r.type === 'reload') {
			// status chip & revisi dimuat ulang (setelah buat / terbit / hapus / refresh dari specsheet)
			try { await q_cbd_articles.run({ specsheet_id: CbdCtrl.seasonId || '' }); } catch (e) { /* abaikan */ }
			if (r.article && r.article !== CbdCtrl.articleId) CbdCtrl.articleId = r.article;
			CbdCtrl.revisionId = r.pick || '';
			return CbdCtrl.loadArticle(r.pick);
		}
	}

