async function (variantId, code) {
		const c = BomCtrl.varCtx || {};
		if (!variantId || !c.line_id || !c.article_id) return;
		BomCtrl.varMsg = null;
		BomCtrl.varBusy = true;
		let res = null;
		try {
			res = await a_bom_use_variant.run({ line_id: c.line_id, article_id: c.article_id, variant_id: variantId });
		} catch (e) {
			const msg = e && e.message;
			if (Util.isSessionError(msg)) {
				closeModal('mdlVarianBaru');
				await removeValue('token');
				showAlert('Session expired. Please log in again.', 'warning');
				navigateTo('Login');
				return;
			}
			BomCtrl.varMsg = { type: 'error', text: Util.cleanError(msg) };
			return;
		} finally {
			BomCtrl.varBusy = false;
		}
		closeModal('mdlVarianBaru');
		BomCtrl.message = { type: 'success', text: BomCtrl.useText(res) };
		showAlert(`${code} used.`, 'success');
		await BomCtrl.reload(['options', 'colors']);
	}

