export default {
	workbook() {
		const MAIN = 'http://schemas.openxmlformats.org/spreadsheetml/2006/main';
		const REL = 'http://schemas.openxmlformats.org/officeDocument/2006/relationships';
		const PKG = 'http://schemas.openxmlformats.org/package/2006/relationships';
		const HEAD = '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>\n';

		const esc = s => String(s)
			.replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F]/g, '')
			.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
		const colName = c => {
			let s = '';
			while (c > 0) {
				const m = (c - 1) % 26;
				s = String.fromCharCode(65 + m) + s;
				c = Math.floor((c - 1) / 26);
			}
			return s;
		};
		const parseRef = ref => {
			const m = /^([A-Z]+)(\d+)$/.exec(String(ref).trim().toUpperCase());
			if (!m) throw new Error('Invalid cell address: ' + ref);
			let c = 0;
			for (let i = 0; i < m[1].length; i++) c = c * 26 + m[1].charCodeAt(i) - 64;
			return [Number(m[2]), c];
		};
		const isDate = v => Object.prototype.toString.call(v) === '[object Date]' && !isNaN(v.getTime());
		const serial = d => (d.getTime() - d.getTimezoneOffset() * 60000) / 86400000 + 25569;

		// ---------- worksheet ----------
		const sheets = [];
		const makeSheet = (name, opts) => {
			const rows = {};
			const cols = {};
			const merges = [];
			let last = 0;
			const getRow = n => {
				if (!rows[n]) {
					const cells = {};
					rows[n] = {
						number: n, height: null, font: null, cells,
						getCell(c) {
							if (!cells[c]) cells[c] = { value: null };
							return cells[c];
						},
					};
					if (n > last) last = n;
				}
				return rows[n];
			};
			return {
				name, pageSetup: opts.pageSetup || null, views: [], rows, cols, merges,
				printTitleRows: null,   // mis. '1:11' = baris 1–11 diulang di tiap halaman cetak
				footer: null,           // teks footer tengah; &P = halaman, &N = jumlah halaman
				getRow,
				getColumn(c) {
					if (!cols[c]) cols[c] = { width: null };
					return cols[c];
				},
				getCell(ref) {
					const rc = parseRef(ref);
					return getRow(rc[0]).getCell(rc[1]);
				},
				addRow(values) {
					const row = getRow(last + 1);
					(values || []).forEach((v, i) => { row.getCell(i + 1).value = v; });
					return row;
				},
				mergeCells(a, b, c, d) {
					if (typeof a === 'string') {
						const p = a.split(':');
						const s = parseRef(p[0]);
						const e = parseRef(p[1]);
						merges.push([s[0], s[1], e[0], e[1]]);
					} else {
						merges.push([a, b, c, d]);
					}
				},
			};
		};

		// ---------- styles ----------
		const registry = () => {
			const list = [];
			const idx = {};
			return {
				list,
				add(key, xml) {
					if (!(key in idx)) { idx[key] = list.length; list.push(xml); }
					return idx[key];
				},
			};
		};
		const fonts = registry();
		const fills = registry();
		const borders = registry();
		const xfs = registry();
		const fmts = registry();
		fonts.add('', '<font><sz val="11"/><name val="Calibri"/><family val="2"/></font>');
		fills.add('', '<fill><patternFill patternType="none"/></fill>');
		fills.add('gray125', '<fill><patternFill patternType="gray125"/></fill>');
		borders.add('', '<border><left/><right/><top/><bottom/><diagonal/></border>');
		xfs.add('', '<xf numFmtId="0" fontId="0" fillId="0" borderId="0" xfId="0"/>');

		const argb = c => (c && c.argb ? `<color rgb="${esc(c.argb)}"/>` : '');
		const fontId = f => {
			if (!f) return 0;
			const key = [f.bold ? 1 : 0, f.italic ? 1 : 0, f.underline ? 1 : 0, f.size || 11, (f.color && f.color.argb) || ''].join('|');
			return fonts.add(key, '<font>' + (f.bold ? '<b/>' : '') + (f.italic ? '<i/>' : '') + (f.underline ? '<u/>' : '')
				+ `<sz val="${f.size || 11}"/>` + argb(f.color) + '<name val="Calibri"/><family val="2"/></font>');
		};
		const fillId = f => {
			const c = f && f.type === 'pattern' && f.pattern === 'solid' && f.fgColor && f.fgColor.argb;
			if (!c) return 0;
			return fills.add(c, `<fill><patternFill patternType="solid"><fgColor rgb="${esc(c)}"/><bgColor indexed="64"/></patternFill></fill>`);
		};
		const borderId = b => {
			if (!b) return 0;
			const side = (tag, s) => (s && s.style ? `<${tag} style="${esc(s.style)}">${argb(s.color)}</${tag}>` : `<${tag}/>`);
			const xml = '<border>' + side('left', b.left) + side('right', b.right) + side('top', b.top) + side('bottom', b.bottom) + '<diagonal/></border>';
			return borders.add(xml, xml);
		};
		const fmtId = f => (f ? 164 + fmts.add(f, f) : 0);
		const alignXml = a => {
			if (!a) return '';
			const v = a.vertical === 'middle' ? 'center' : a.vertical;
			const attrs = (a.horizontal ? ` horizontal="${esc(a.horizontal)}"` : '') + (v ? ` vertical="${esc(v)}"` : '') + (a.wrapText ? ' wrapText="1"' : '');
			return attrs ? `<alignment${attrs}/>` : '';
		};
		const styleId = (cell, rowFont) => {
			const nf = fmtId(cell.numFmt || (isDate(cell.value) ? 'dd-mm-yyyy' : null));
			const fo = fontId(cell.font || rowFont);
			const fi = fillId(cell.fill);
			const bo = borderId(cell.border);
			const al = alignXml(cell.alignment);
			if (!nf && !fo && !fi && !bo && !al) return 0;
			const xml = `<xf numFmtId="${nf}" fontId="${fo}" fillId="${fi}" borderId="${bo}" xfId="0"`
				+ (nf ? ' applyNumberFormat="1"' : '') + (fo ? ' applyFont="1"' : '') + (fi ? ' applyFill="1"' : '')
				+ (bo ? ' applyBorder="1"' : '') + (al ? ` applyAlignment="1">${al}</xf>` : '/>');
			return xfs.add(xml, xml);
		};

		// ---------- sheet XML ----------
		const cellXml = (ref, cell, rowFont) => {
			const s = styleId(cell, rowFont);
			const sa = s ? ` s="${s}"` : '';
			let v = cell.value;
			if (v === null || v === undefined || v === '') return s ? `<c r="${ref}"${sa}/>` : '';
			if (isDate(v)) v = serial(v);
			if (typeof v === 'number') return Number.isFinite(v) ? `<c r="${ref}"${sa}><v>${v}</v></c>` : (s ? `<c r="${ref}"${sa}/>` : '');
			if (typeof v === 'boolean') return `<c r="${ref}"${sa} t="b"><v>${v ? 1 : 0}</v></c>`;
			if (typeof v === 'object' && v.formula !== undefined) {
				const f = `<f>${esc(String(v.formula).replace(/^=/, ''))}</f>`;
				const r = v.result;
				if (typeof r === 'number' && Number.isFinite(r)) return `<c r="${ref}"${sa}>${f}<v>${r}</v></c>`;
				if (typeof r === 'string') return `<c r="${ref}"${sa} t="str">${f}<v>${esc(r)}</v></c>`;
				return `<c r="${ref}"${sa}>${f}</c>`;
			}
			return `<c r="${ref}"${sa} t="inlineStr"><is><t xml:space="preserve">${esc(v)}</t></is></c>`;
		};
		const sheetXml = ws => {
			const out = [HEAD, `<worksheet xmlns="${MAIN}" xmlns:r="${REL}">`];
			if (ws.pageSetup && ws.pageSetup.fitToPage) out.push('<sheetPr><pageSetUpPr fitToPage="1"/></sheetPr>');
			const fr = (ws.views || []).find(x => x && x.state === 'frozen');
			if (fr && (fr.xSplit || fr.ySplit)) {
				const xs = fr.xSplit || 0;
				const ys = fr.ySplit || 0;
				const pane = xs && ys ? 'bottomRight' : (ys ? 'bottomLeft' : 'topRight');
				out.push('<sheetViews><sheetView workbookViewId="0"><pane' + (xs ? ` xSplit="${xs}"` : '') + (ys ? ` ySplit="${ys}"` : '')
					+ ` topLeftCell="${colName(xs + 1)}${ys + 1}" activePane="${pane}" state="frozen"/><selection pane="${pane}"/></sheetView></sheetViews>`);
			} else {
				out.push('<sheetViews><sheetView workbookViewId="0"/></sheetViews>');
			}
			out.push('<sheetFormatPr defaultRowHeight="15"/>');
			const cn = Object.keys(ws.cols).map(Number).filter(c => ws.cols[c].width).sort((a, b) => a - b);
			if (cn.length) {
				out.push('<cols>');
				cn.forEach(c => out.push(`<col min="${c}" max="${c}" width="${ws.cols[c].width}" customWidth="1"/>`));
				out.push('</cols>');
			}
			out.push('<sheetData>');
			Object.keys(ws.rows).map(Number).sort((a, b) => a - b).forEach(n => {
				const row = ws.rows[n];
				const cells = Object.keys(row.cells).map(Number).sort((a, b) => a - b)
					.map(c => cellXml(colName(c) + n, row.cells[c], row.font)).join('');
				if (cells || row.height) {
					out.push(`<row r="${n}"` + (row.height ? ` ht="${row.height}" customHeight="1"` : '') + `>${cells}</row>`);
				}
			});
			out.push('</sheetData>');
			if (ws.merges.length) {
				out.push(`<mergeCells count="${ws.merges.length}">`);
				ws.merges.forEach(m => out.push(`<mergeCell ref="${colName(m[1])}${m[0]}:${colName(m[3])}${m[2]}"/>`));
				out.push('</mergeCells>');
			}
			out.push('<pageMargins left="0.4" right="0.4" top="0.6" bottom="0.6" header="0.3" footer="0.3"/>');
			const ps = ws.pageSetup;
			if (ps) {
				out.push('<pageSetup' + (ps.paperSize ? ` paperSize="${ps.paperSize}"` : '') + (ps.orientation ? ` orientation="${esc(ps.orientation)}"` : '')
					+ (ps.fitToPage ? ` fitToWidth="${ps.fitToWidth ?? 1}" fitToHeight="${ps.fitToHeight ?? 0}"` : '') + '/>');
			}
			if (ws.footer) out.push(`<headerFooter><oddFooter>&amp;C${esc(ws.footer)}</oddFooter></headerFooter>`);
			out.push('</worksheet>');
			return out.join('');
		};

		// ---------- package ----------
		const files = wb => {
			const names = {};
			const list = sheets.map((ws, i) => {
				let nm = String(ws.name || `Sheet${i + 1}`).replace(/[\\/?*[\]:]/g, ' ').slice(0, 31).trim() || `Sheet${i + 1}`;
				while (names[nm.toLowerCase()]) nm = (nm.slice(0, 28) + ' ' + (i + 1)).slice(0, 31);
				names[nm.toLowerCase()] = true;
				return { name: nm, xml: sheetXml(ws), titles: ws.printTitleRows };
			});
			const defined = list.map((s, i) => {
				const m = /^(\d+):(\d+)$/.exec(String(s.titles || ''));
				return m ? `<definedName name="_xlnm.Print_Titles" localSheetId="${i}">'${esc(s.name.replace(/'/g, "''"))}'!$${m[1]}:$${m[2]}</definedName>` : '';
			}).join('');
			const fmtXml = fmts.list.length
				? `<numFmts count="${fmts.list.length}">` + fmts.list.map((f, i) => `<numFmt numFmtId="${164 + i}" formatCode="${esc(f)}"/>`).join('') + '</numFmts>'
				: '';
			const styles = HEAD + `<styleSheet xmlns="${MAIN}">` + fmtXml
				+ `<fonts count="${fonts.list.length}">${fonts.list.join('')}</fonts>`
				+ `<fills count="${fills.list.length}">${fills.list.join('')}</fills>`
				+ `<borders count="${borders.list.length}">${borders.list.join('')}</borders>`
				+ '<cellStyleXfs count="1"><xf numFmtId="0" fontId="0" fillId="0" borderId="0"/></cellStyleXfs>'
				+ `<cellXfs count="${xfs.list.length}">${xfs.list.join('')}</cellXfs>`
				+ '<cellStyles count="1"><cellStyle name="Normal" xfId="0" builtinId="0"/></cellStyles></styleSheet>';
			const created = isDate(wb.created) ? wb.created : new Date();
			const iso = created.toISOString().replace(/\.\d+Z$/, 'Z');
			return [
				['[Content_Types].xml', HEAD + '<Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types">'
					+ '<Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/>'
					+ '<Default Extension="xml" ContentType="application/xml"/>'
					+ '<Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/>'
					+ list.map((s, i) => `<Override PartName="/xl/worksheets/sheet${i + 1}.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/>`).join('')
					+ '<Override PartName="/xl/styles.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.styles+xml"/>'
					+ '<Override PartName="/docProps/core.xml" ContentType="application/vnd.openxmlformats-package.core-properties+xml"/>'
					+ '</Types>'],
				['_rels/.rels', HEAD + `<Relationships xmlns="${PKG}">`
					+ `<Relationship Id="rId1" Type="${REL}/officeDocument" Target="xl/workbook.xml"/>`
					+ `<Relationship Id="rId2" Type="${PKG}/metadata/core-properties" Target="docProps/core.xml"/>`
					+ '</Relationships>'],
				['docProps/core.xml', HEAD + '<cp:coreProperties xmlns:cp="http://schemas.openxmlformats.org/package/2006/metadata/core-properties"'
					+ ' xmlns:dc="http://purl.org/dc/elements/1.1/" xmlns:dcterms="http://purl.org/dc/terms/"'
					+ ' xmlns:xsi="http://www.w3.org/2001/XMLSchema-instance">'
					+ `<dc:creator>${esc(wb.creator || '')}</dc:creator>`
					+ `<dcterms:created xsi:type="dcterms:W3CDTF">${iso}</dcterms:created>`
					+ `<dcterms:modified xsi:type="dcterms:W3CDTF">${iso}</dcterms:modified></cp:coreProperties>`],
				['xl/workbook.xml', HEAD + `<workbook xmlns="${MAIN}" xmlns:r="${REL}"><bookViews><workbookView/></bookViews><sheets>`
					+ list.map((s, i) => `<sheet name="${esc(s.name)}" sheetId="${i + 1}" r:id="rId${i + 1}"/>`).join('')
					+ '</sheets>' + (defined ? `<definedNames>${defined}</definedNames>` : '')
					+ '<calcPr calcId="191029" fullCalcOnLoad="1"/></workbook>'],
				['xl/_rels/workbook.xml.rels', HEAD + `<Relationships xmlns="${PKG}">`
					+ list.map((s, i) => `<Relationship Id="rId${i + 1}" Type="${REL}/worksheet" Target="worksheets/sheet${i + 1}.xml"/>`).join('')
					+ `<Relationship Id="rId${list.length + 1}" Type="${REL}/styles" Target="styles.xml"/></Relationships>`],
				['xl/styles.xml', styles],
			].concat(list.map((s, i) => [`xl/worksheets/sheet${i + 1}.xml`, s.xml]));
		};

		// ---------- zip (STORE, tanpa kompresi) ----------
		const utf8 = s => {
			const out = [];
			for (let i = 0; i < s.length; i++) {
				let c = s.charCodeAt(i);
				if (c >= 0xD800 && c <= 0xDBFF && i + 1 < s.length) {
					const d = s.charCodeAt(i + 1);
					if (d >= 0xDC00 && d <= 0xDFFF) { c = 0x10000 + ((c - 0xD800) << 10) + (d - 0xDC00); i++; }
				}
				if (c >= 0xD800 && c <= 0xDFFF) c = 0xFFFD;
				if (c < 0x80) out.push(c);
				else if (c < 0x800) out.push(0xC0 | (c >> 6), 0x80 | (c & 63));
				else if (c < 0x10000) out.push(0xE0 | (c >> 12), 0x80 | ((c >> 6) & 63), 0x80 | (c & 63));
				else out.push(0xF0 | (c >> 18), 0x80 | ((c >> 12) & 63), 0x80 | ((c >> 6) & 63), 0x80 | (c & 63));
			}
			return out;
		};
		const CRC = [];
		for (let n = 0; n < 256; n++) {
			let c = n;
			for (let k = 0; k < 8; k++) c = c & 1 ? 0xEDB88320 ^ (c >>> 1) : c >>> 1;
			CRC.push(c >>> 0);
		}
		const crc32 = bytes => {
			let c = 0xFFFFFFFF;
			for (let i = 0; i < bytes.length; i++) c = CRC[(c ^ bytes[i]) & 0xFF] ^ (c >>> 8);
			return (c ^ 0xFFFFFFFF) >>> 0;
		};
		const zip = (entries, when) => {
			const out = [];
			const central = [];
			const u16 = (arr, v) => { arr.push(v & 0xFF, (v >>> 8) & 0xFF); };
			const u32 = (arr, v) => { arr.push(v & 0xFF, (v >>> 8) & 0xFF, (v >>> 16) & 0xFF, (v >>> 24) & 0xFF); };
			const copy = (arr, src) => { for (let i = 0; i < src.length; i++) arr.push(src[i]); };
			const time = (when.getHours() << 11) | (when.getMinutes() << 5) | (when.getSeconds() >> 1);
			const date = ((Math.max(when.getFullYear(), 1980) - 1980) << 9) | ((when.getMonth() + 1) << 5) | when.getDate();
			entries.forEach(e => {
				const name = utf8(e[0]);
				const data = utf8(e[1]);
				const crc = crc32(data);
				const offset = out.length;
				u32(out, 0x04034B50); u16(out, 20); u16(out, 0x0800); u16(out, 0); u16(out, time); u16(out, date);
				u32(out, crc); u32(out, data.length); u32(out, data.length); u16(out, name.length); u16(out, 0);
				copy(out, name);
				copy(out, data);
				u32(central, 0x02014B50); u16(central, 20); u16(central, 20); u16(central, 0x0800); u16(central, 0);
				u16(central, time); u16(central, date); u32(central, crc); u32(central, data.length); u32(central, data.length);
				u16(central, name.length); u16(central, 0); u16(central, 0); u16(central, 0); u16(central, 0); u32(central, 0);
				u32(central, offset);
				copy(central, name);
			});
			const cdOffset = out.length;
			copy(out, central);
			u32(out, 0x06054B50); u16(out, 0); u16(out, 0); u16(out, entries.length); u16(out, entries.length);
			u32(out, central.length); u32(out, cdOffset); u16(out, 0);
			return out;
		};
		const base64 = bytes => {
			const t = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';
			const out = [];
			for (let i = 0; i < bytes.length; i += 3) {
				const x = (bytes[i] << 16) | ((bytes[i + 1] || 0) << 8) | (bytes[i + 2] || 0);
				out.push(t[(x >> 18) & 63] + t[(x >> 12) & 63]
					+ (i + 1 < bytes.length ? t[(x >> 6) & 63] : '=') + (i + 2 < bytes.length ? t[x & 63] : '='));
			}
			return out.join('');
		};

		const wb = {
			creator: '',
			created: new Date(),
			addWorksheet(name, opts) {
				const ws = makeSheet(name, opts || {});
				sheets.push(ws);
				return ws;
			},
			toBase64() {
				return base64(zip(files(wb), isDate(wb.created) ? wb.created : new Date()));
			},
		};
		return wb;
	},
}

unpublishedCollection.body:
export default {
	busy: false,
	step: '',      // langkah export yang sedang berjalan (untuk pesan error)

	NAVY: 'FF122A52',
	YELLOW: 'FFFEF08A',   // R17: baris tanpa Material Code (sama dengan sel kuning Excel specsheet)
	GROUP_FILL: 'FFDCE4F3',
	MISSING_FILL: 'FFFCEFD8',
	RP: '_-"Rp"* #,##0.00_-;\\-"Rp"* #,##0.00_-;_-"Rp"* "-"??_-;_-@_-',
	USD: '_-[$$-409]* #,##0.0000_ ;_-[$$-409]* \\-#,##0.0000\\ ;_-[$$-409]* "-"??_ ;_-@_ ',
	COST_LABEL: { LABOUR: 'Direct Labour', AMORTIZATION: 'Amortization', ADJUSTMENT: 'Adjustment', OTHER: 'Other' },

	canExport() {
		return !!CbdCtrl.revision() && !this.busy;
	},

	n(v) {
		if (v === null || v === undefined || v === '') return null;
		const x = Number(v);
		return Number.isFinite(x) ? x : null;
	},

	fileName(...parts) {
		return parts.filter(p => p).join('_').replace(/[\\/:*?"<>|\s]+/g, '-') + '.xlsx';
	},

	box(row, from, to) {
		for (let c = from; c <= to; c++) {
			row.getCell(c).border = this.thin();
		}
	},

	fill(row, from, to, argb) {
		for (let c = from; c <= to; c++) row.getCell(c).fill = { type: 'pattern', pattern: 'solid', fgColor: { argb } };
	},

	// Rumus + hasil (hasil dari DB supaya tampil tanpa dihitung ulang)
	f(formula, result) {
		return result === null || result === undefined ? { formula } : { formula, result };
	},

	// Garis tipis - objek baru setiap kali (gaya jangan disimpan sebagai variabel JSObject)
	thin() {
		const s = () => ({ style: 'thin', color: { argb: 'FFC9CFDB' } });
		return { top: s(), left: s(), bottom: s(), right: s() };
	},

	// Tulis file (JSObject XlsxWriter, tanpa ExcelJS - T43) lalu unduh. this.step = langkah yang sedang berjalan.
	async save(wb, name) {
		this.step = 'writing the file';
		const b64 = wb.toBase64();
		this.step = 'downloading';
		const mime = 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet';
		await download(`data:${mime};base64,${b64}`, name, mime);
	},

	// ---- tombol Export Excel ----
	async exportExcel() {
		const m = CbdCtrl.model();
		const s = CbdCtrl.season();
		const a = CbdCtrl.article();
		const r = CbdCtrl.revision();
		if (!m || !s || !a || !r) return showAlert('Open a CBD revision first.', 'warning');
		this.busy = true;
		this.step = 'loading the change breakdown';
		try {
			let withBridge = true;           // gagal dimuat -> export tetap jalan tanpa blok rincian
			try {
				await q_cbd_bridge.run({ revision_id: r.id });
			} catch (e) {
				withBridge = false;
			}
			this.step = 'building the content';
			const wb = this.build(m, s, a, r, withBridge);
			await this.save(wb, this.fileName('CBD', m.name, s.season, CbdCtrl.artLabel(a), `${Util.stageLabel(r.stage)}-r${r.revision_no}`, r.status === 'DRAFT' ? 'DRAFT' : ''));
			showAlert('CBD Excel file downloaded.', 'success');
		} catch (e) {
			showAlert(`Export failed while ${this.step}: ` + Util.cleanError((e && e.message) || String(e)), 'error');
		} finally {
			this.busy = false;
		}
	},

	// Kolom: A No · B Component Name · C Material description · D Thickness · E Unit · F Color · G Yield · H Usage ·
	// I Loss % · J Unit price USD · K Unit price IDR · L Cost/pr (Rp) · M Supplier · N Remarks · O Asal harga / nilai
	build(m, s, a, r, withBridge) {
		const N = 15;
		const lines = CbdGridCtrl.lines();
		const rc = CbdGridCtrl.recap() || {};
		const items = CbdGridCtrl.costItems();
		const log = r.status === 'PUBLISHED' ? CbdCtrl.logFor(r.id) : null;
		const rate = this.n(r.exchange_rate);

		const wb = XlsxWriter.workbook();
		wb.creator = (Auth.me && Auth.me.full_name) || '';
		wb.created = new Date();
		const ws = wb.addWorksheet(`${CbdCtrl.artLabel(a)} ${Util.revLabel(r)}`.slice(0, 31), {   // R19: tanpa nomor = colorway
			pageSetup: { orientation: 'landscape', paperSize: 9, fitToPage: true, fitToWidth: 1, fitToHeight: 0 },
		});
		[6, 24, 34, 11, 9, 18, 10, 10, 8, 13, 15, 17, 18, 20, 16].forEach((w, i) => { ws.getColumn(i + 1).width = w; });

		// ---- header (baris 1–8) ----
		ws.getCell('A1').value = 'Cost Breakdown Sheet';
		ws.getCell('A1').font = { bold: true, size: 16, color: { argb: this.NAVY } };
		ws.getCell('A2').value = 'Confidential Information';
		ws.getCell('A2').font = { italic: true, color: { argb: 'FF6B7280' } };
		ws.getCell('K2').value = 'Date';
		// R12 (T67): tanggal WIB (sel Excel memakai tanggal lokal PC)
		ws.getCell('L2').value = new Date(moment(r.status === 'PUBLISHED' && r.published_at ? r.published_at : undefined)
			.utcOffset(7).format('YYYY-MM-DD') + 'T00:00:00');
		ws.getCell('L2').numFmt = 'dd-mmm-yyyy';
		ws.getCell('K3').value = '1 $ =';
		ws.getCell('K3').alignment = { horizontal: 'right' };
		ws.getCell('L3').value = rate;
		ws.getCell('L3').numFmt = this.RP;
		ws.getCell('L3').font = { bold: true, size: 14 };
		const v = x => x || '-';
		const info = [
			['Model Name', `${m.name} (${v(m.factory_name)}); Mold: ${v(m.outsole_mold)}; Last: ${v(m.last_no)}; Size Range: ${v(m.size_range)}`],
			['Article #', `${a.code}`],
			['Construction', v(m.construction)],
			['Color', v(a.colorway)],
			['Season / Revision', `${s.season} · ${Util.revLabel(r)} · ${r.status}`
				+ (r.status === 'PUBLISHED' ? ` · published by ${r.published_by || '-'}` : ' · NOT PUBLISHED')
				+ ` · reference specsheet ${r.spec_label || '-'}`],
		];
		info.forEach(([k, val], i) => {
			ws.getCell(`B${4 + i}`).value = k;
			ws.getCell(`B${4 + i}`).font = { bold: true };
			ws.getCell(`C${4 + i}`).value = val;
		});
		ws.getCell('C8').font = { bold: true, color: { argb: r.status === 'PUBLISHED' ? 'FF16A34A' : 'FFDC2626' } };

		// ---- header tabel (baris 10–11) ----
		const h1 = ws.getRow(10);
		const h2 = ws.getRow(11);
		['No', 'Component Name', 'Material description', 'Dimension', 'Unit', 'Color', 'Yield', 'Usage', 'Loss %',
			'Unit Price', '', 'Cost/pr (Rp)', 'Supplier', 'Remarks', 'Source'].forEach((t, i) => { h1.getCell(i + 1).value = t; });
		h2.getCell(10).value = 'USD';
		h2.getCell(11).value = 'IDR';
		ws.mergeCells('J10:K10');
		[1, 2, 3, 4, 5, 6, 7, 8, 9, 12, 13, 14, 15].forEach(c => ws.mergeCells(10, c, 11, c));
		[h1, h2].forEach(row => {
			this.fill(row, 1, N, this.NAVY);
			this.box(row, 1, N);
			for (let c = 1; c <= N; c++) {
				row.getCell(c).font = { bold: true, color: { argb: 'FFFFFFFF' } };
				row.getCell(c).alignment = { horizontal: 'center', vertical: 'middle', wrapText: true };
			}
		});

		// ---- baris material ----
		const writeLine = (l, counted) => {
			const row = ws.addRow([]);
			const i = row.number;
			const y = this.n(l.yield_value);
			const p = this.n(l.price_original);
			row.getCell(1).value = l.is_sub ? '' : (l.display_no || '');
			row.getCell(2).value = (l.is_sub ? '↳ ' : '') + (l.display_name || '') + (l.is_local ? ' (local)' : '');
			row.getCell(3).value = `${l.material_name || ''}${l.material_code ? ' [' + l.material_code + ']'
				: l.price_method === 'CATALOG' ? ' (no code)' : ''}`;
			row.getCell(4).value = l.thickness || '';
			row.getCell(5).value = l.uom || '';
			row.getCell(6).value = l.color || '';
			row.getCell(7).value = y;
			row.getCell(8).value = y ? this.f(`1/G${i}`, this.n(l.usage_value)) : null;
			row.getCell(9).value = this.n(l.loss_pct) ?? 0;
			if (p !== null && l.currency === 'USD') {
				row.getCell(10).value = p;
				row.getCell(11).value = this.f(`J${i}*$L$3`, this.n(l.price_idr));
			} else if (p !== null) {
				row.getCell(11).value = p;
			}
			if (counted && l.no_charge) {
				row.getCell(12).value = 0;          // R11: tanpa biaya - harga termasuk baris lain
			} else if (counted && y && p !== null && (l.currency === 'IDR' || rate)) {
				row.getCell(12).value = this.f(`H${i}*(1+I${i}/100)*K${i}`, this.n(l.cost_per_pair));
			}
			row.getCell(13).value = l.supplier_name || '';
			row.getCell(14).value = l.remarks || '';
			const src = { MASTER: 'master price', OVERRIDE: 'override', QUOTATION: 'quotation', ESTIMATE: 'estimate' }[l.price_source] || 'no price';
			const org = { INPUT: '', COPIED: ' · copy', CARRIED_FROM_REPLACED: ' · replaced material' }[l.value_origin] || '';
			row.getCell(15).value = l.no_charge ? `no charge: ${l.no_charge_reason || '-'}`
				: src + org + (l.price_source === 'OVERRIDE' && l.price_override_reason ? `: ${l.price_override_reason}` : '');
			row.getCell(7).numFmt = '#,##0.00####';
			row.getCell(8).numFmt = '0.000000';
			row.getCell(9).numFmt = '0.00';
			row.getCell(10).numFmt = this.USD;
			row.getCell(11).numFmt = this.RP;
			row.getCell(12).numFmt = this.RP;
			this.box(row, 1, N);
			for (let c = 1; c <= N; c++) row.getCell(c).alignment = { vertical: 'top', wrapText: c <= 6 || c >= 13 };
			if (!counted) for (let c = 1; c <= N; c++) row.getCell(c).font = { color: { argb: 'FF9CA3AF' } };
			// R17: baris tanpa Material Code (Pullover / Preview) kuning, sama dengan sel kuning di Excel specsheet
			if (counted && !l.material_code && l.price_method === 'CATALOG') this.fill(row, 1, N, this.YELLOW);
			return i;
		};

		const groupHeader = (label, argb) => {
			const row = ws.addRow([label]);
			ws.mergeCells(row.number, 1, row.number, N);
			row.getCell(1).font = { bold: true, color: { argb: this.NAVY } };
			this.fill(row, 1, N, argb);
		};

		const active = lines.filter(l => l.status === 'ACTIVE');
		const missing = lines.filter(l => l.status !== 'ACTIVE');
		const groups = [];
		active.forEach(l => {
			let g = groups[groups.length - 1];
			if (!g || g.code !== l.group_code) groups.push(g = { code: l.group_code, name: l.group_name, lines: [] });
			g.lines.push(l);
		});
		const subtotalCells = [];
		const gc = rc.group_costs || {};
		groups.forEach(g => {
			groupHeader(`${String(g.code || '').toLowerCase()}. ${g.name || ''}`, this.GROUP_FILL);
			const rows = g.lines.map(l => writeLine(l, true));
			const st = ws.addRow([]);
			st.getCell(2).value = `Subtotal ${String(g.code || '').toUpperCase()} · ${g.name || ''}`;
			st.getCell(12).value = this.f(`SUM(L${rows[0]}:L${rows[rows.length - 1]})`, this.n(gc[g.code]) ?? 0);
			st.getCell(12).numFmt = this.RP;
			st.font = { bold: true };
			this.box(st, 1, N);
			subtotalCells.push(`L${st.number}`);
			ws.addRow([]);
		});
		if (!groups.length) ws.addRow(['No CBD lines yet.']);
		if (missing.length) {
			groupHeader(`Missing from specsheet (MISSING_IN_SPEC): ${missing.length} lines, not counted`, this.MISSING_FILL);
			missing.forEach(l => writeLine(l, false));
			ws.addRow([]);
		}

		// ---- Cost recapitulation (kolom G–L, keterangan di M) ----
		ws.addRow([]);
		const title = ws.addRow([]);
		title.getCell(7).value = 'Cost recapitulation';
		title.getCell(7).font = { bold: true, size: 12, color: { argb: this.NAVY } };
		const recapRow = (label, value, note, bold) => {
			const row = ws.addRow([]);
			row.getCell(7).value = label;
			row.getCell(12).value = value;
			row.getCell(12).numFmt = this.RP;
			if (note) row.getCell(13).value = note;
			if (bold) row.font = { bold: true };
			ws.mergeCells(row.number, 7, row.number, 11);
			this.box(row, 7, 13);
			return row.number;
		};
		const letter = i => String.fromCharCode(97 + i) + '.';
		const first = recapRow(`${letter(0)} Material Cost`,
			this.f(subtotalCells.length ? `SUM(${subtotalCells.join(',')})` : '0', this.n(rc.material_cost) ?? 0), '', true);
		let last = first;
		items.forEach((it, i) => {
			last = recapRow(`${letter(i + 1)} ${it.name || this.COST_LABEL[it.item_type]}`, this.n(it.amount) ?? 0, it.remarks || '');
		});
		const fobRow = recapRow('ACTUAL FOB', this.f(`SUM(L${first}:L${last})`, this.n(rc.actual_fob)), 'material cost + all costs', true);
		ws.getRow(fobRow).getCell(12).fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: this.GROUP_FILL } };

		ws.addRow([]);
		const tRow = ws.addRow([]);
		tRow.getCell(11).value = 'TARGET FOB';
		tRow.getCell(12).value = this.n(rc.target_fob);
		tRow.getCell(12).numFmt = this.RP;
		const t = tRow.number;
		const vRow = ws.addRow([]);
		if (tRow.getCell(12).value !== null) {
			vRow.getCell(11).value = this.f(`IF(L${fobRow}>L${t},"OVER",IF(L${fobRow}<L${t},"UNDER","MATCH"))`, rc.variance_label || null);
			vRow.getCell(12).value = this.f(`L${fobRow}-L${t}`, this.n(rc.variance));
			vRow.getCell(12).numFmt = this.RP;
			vRow.getCell(11).font = { bold: true, color: { argb: rc.variance_label === 'OVER' ? 'FFDC2626' : 'FF16A34A' } };
		}
		[tRow, vRow].forEach(row => { row.getCell(11).alignment = { horizontal: 'right' }; });

		// ---- R5: PO (mis. SMS = Actual FOB x 1,25). Selling price & margin tidak ada di CBD. ----
		const factor = this.n(rc.po_factor);
		if (factor) {
			const pRow = recapRow(`PO ${Util.stageLabel(r.stage)} (Actual FOB × ${String(factor).replace('.', ',')})`,
				this.f(`ROUND(L${fobRow}*${factor},2)`, this.n(rc.po_price)), 'PO price to brand', true);
			ws.getRow(pRow).getCell(12).fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: this.GROUP_FILL } };
		}

		// ---- change log revisi ini ----
		if (log) {
			ws.addRow([]);
			const c = ws.addRow(['', 'Change log']);
			c.getCell(2).font = { bold: true };
			const ch = ws.addRow(['', 'Date', 'Category', 'By', '', 'Reason']);
			ch.font = { bold: true };
			ws.addRow(['', moment(log.created_at).utcOffset(7).format('DD-MM-YYYY HH:mm'), log.category, log.created_by, '', log.reason]);
		}

		// ---- R11 (A4): rincian perubahan vs revisi terbit sebelumnya ----
		const bridge = withBridge ? CbdCtrl.bridgeRows() : [];
		if (bridge.length) {
			ws.addRow([]);
			const bt = ws.addRow(['', `Change breakdown vs ${bridge[0].prev_label || 'previous revision'}`]);
			bt.getCell(2).font = { bold: true, color: { argb: this.NAVY } };
			const bh = ws.addRow(['', 'Category', 'Description']);
			bh.getCell(12).value = 'Value (Rp)';
			ws.mergeCells(bh.number, 3, bh.number, 11);
			this.fill(bh, 2, 12, this.GROUP_FILL);
			this.box(bh, 2, 12);
			bh.font = { bold: true };
			const firstB = bh.number + 1;
			bridge.forEach(x => {
				const row = ws.addRow(['', x.category_label || x.category, x.description || '']);
				row.getCell(12).value = this.n(x.amount);
				row.getCell(12).numFmt = this.RP;
				ws.mergeCells(row.number, 3, row.number, 11);
				row.getCell(3).alignment = { wrapText: true, vertical: 'top' };
				this.box(row, 2, 12);
			});
			const lastB = firstB + bridge.length - 1;
			const tot = ws.addRow(['', 'Actual FOB difference',
				`${bridge[0].prev_label || ''}: ${Util.fmtNum(bridge[0].prev_fob, 2)} → ${Util.revLabel(r)}: ${Util.fmtNum(bridge[0].fob, 2)}`]);
			const delta = this.n(bridge[0].fob) !== null && this.n(bridge[0].prev_fob) !== null
				? this.n(bridge[0].fob) - this.n(bridge[0].prev_fob) : null;
			tot.getCell(12).value = this.f(`SUM(L${firstB}:L${lastB})`, delta);
			tot.getCell(12).numFmt = this.RP;
			ws.mergeCells(tot.number, 3, tot.number, 11);
			this.box(tot, 2, 12);
			tot.font = { bold: true };
		}

		ws.views = [{ state: 'frozen', xSplit: 3, ySplit: 11 }];
		return wb;
	},
}

