export default {
	// State yang dikirim ke cwLogin lewat Default model
	view: 'login',      // 'login' | 'change'
	busy: false,
	forced: false,      // wajib ganti password (password sementara)
	message: null,      // { type, text }
	lastEmail: '',      // email terakhir (isi awal field email)

	setMessage(type, text) {
		this.message = text ? { type, text } : null;
	},

	openChange(forced) {
		this.forced = !!forced;
		this.view = 'change';
		this.setMessage(null);
	},

	// Kembalikan tampilan ke awal sebelum pindah ke Beranda - state JSObject tetap tersimpan selama sesi
	// browser, jadi tanpa ini page Login berikutnya masih menampilkan form ganti password (T46).
	resetView() {
		this.view = 'login';
		this.forced = false;
		this.setMessage(null);
	},

	goHome() {
		this.resetView();
		navigateTo('Home');
	},

	async onPageLoad() {
		const mode = appsmith.URL.queryParams.mode;
		this.view = 'login';
		this.busy = false;
		this.forced = false;
		this.setMessage(null);
		this.lastEmail = appsmith.store.lastEmail || this.lastEmail;
		if (appsmith.store.doLogout) {
			await removeValue('doLogout');
			await this.logout();
			return;
		}
		if (!appsmith.store.token) return;
		const me = await this.loadMe();
		if (!me) {
			await removeValue('token');
			return;
		}
		if (me.must_change_password || mode === 'ganti') {
			this.openChange(me.must_change_password);
			return;
		}
		this.goHome();
	},

	async loadMe() {
		try {
			await q_me.run();
		} catch (e) {
			return null;
		}
		return (q_me.data && q_me.data[0]) || null;
	},

	async login() {
		// Baca dulu dari model sebelum state berubah (model di-reset saat Default model berubah)
		const email = (cwLogin.model.email || '').trim().toLowerCase();
		const password = cwLogin.model.password || '';
		const remember = cwLogin.model.remember === true;
		if (!email || !password) {
			this.setMessage('error', 'Enter email and password.');
			return;
		}
		this.lastEmail = email;
		this.setMessage(null);
		this.busy = true;
		try {
			await a_login.run({ email, password, remember });
		} catch (e) {
			this.setMessage('error', Util.cleanError(e && e.message));
			return;
		} finally {
			this.busy = false;
		}
		const r = a_login.data && a_login.data[0];
		if (!r || !r.ok) {
			this.setMessage('error', (r && r.message) || 'Login failed.');
			return;
		}
		await storeValue('token', r.token, true);
		await storeValue('lastEmail', email, true);
		if (r.must_change_password) {
			await this.loadMe();
			this.openChange(true);
			return;
		}
		this.goHome();
	},

	async changePassword() {
		const oldPass = cwLogin.model.oldPass || '';
		const newPass = cwLogin.model.newPass || '';
		if (!oldPass || !newPass) {
			this.setMessage('error', 'Enter the old and new password.');
			return;
		}
		this.setMessage(null);
		this.busy = true;
		try {
			await a_change_password.run({ oldPass, newPass });
		} catch (e) {
			const msg = e && e.message;
			if (Util.isSessionError(msg)) {
				await removeValue('token');
				this.view = 'login';
				this.forced = false;
				this.setMessage('error', 'Session expired. Please log in again.');
			} else {
				this.setMessage('error', Util.cleanError(msg));
			}
			return;
		} finally {
			this.busy = false;
		}
		showAlert('Password changed.', 'success');
		this.goHome();
	},

	// Batal: kalau wajib ganti password -> keluar; kalau tidak -> kembali ke Beranda
	async cancelChange() {
		if (this.forced) {
			await this.logout();
			return;
		}
		this.goHome();
	},

	async logout() {
		if (appsmith.store.token) {
			try { await a_logout.run(); } catch (e) { /* sesi mungkin sudah habis */ }
		}
		await removeValue('token');
		this.view = 'login';
		this.forced = false;
		this.setMessage('info', 'You are logged out.');
	},
}

